window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s9-295","number":295,"surah":9,"verses":[49],"verseLabel":"التوبة: 49","question":"لماذا جاء الرد: ﴿ألا في الفتنة سقطوا﴾؟","answer":"الرد يقلب حجته عليه: الفتنة التي فر منها بزعمِه هي عين النفاق والمعصية التي وقع فيها بطلب التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص350–353.","url":""}]},{"id":"s9-296","number":296,"surah":9,"verses":[49],"verseLabel":"التوبة: 49","question":"لماذا عبّر بـ﴿سقطوا﴾ في الفتنة؟","answer":"السقوط يصور الفتنة حفرة هوى فيها من غير قدرة على الخلاص، وهو أبلغ من مجرد الدخول فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص352–354.","url":""}]},{"id":"s9-297","number":297,"surah":9,"verses":[49],"verseLabel":"التوبة: 49","question":"لماذا افتتحت الجملة بـ﴿ألا﴾؟","answer":"﴿ألا﴾ أداة تنبيه واستفتاح تلفت السمع إلى الحقيقة المخالفة لدعواه وتحقق وقوعه في الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص353–355.","url":""}]},{"id":"s9-298","number":298,"surah":9,"verses":[49],"verseLabel":"التوبة: 49","question":"ما الصورة في قوله: ﴿وإن جهنم لمحيطة بالكافرين﴾؟","answer":"صُورت جهنم محيطة بهم من كل جانب؛ فهي تحاصرهم بعلم الله وأسبابها في الدنيا، ثم تضمهم حقيقة في الآخرة فلا مهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص354–356.","url":""}]},{"id":"s9-299","number":299,"surah":9,"verses":[50],"verseLabel":"التوبة: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تصبك حسنة تسؤهم وإن تصبك مصيبة يقولوا قد أخذنا أمرنا﴾؟","answer":"تكشف الجملة أن المنافقين يتأذون بما يصيب النبي ﷺ والمؤمنين من خير، ويفرحون بالمصيبة زاعمين أنهم احتاطوا لأنفسهم؛ فهي تصور انقلاب موازينهم وفساد سرائرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص357–360.","url":""}]},{"id":"s9-300","number":300,"surah":9,"verses":[50],"verseLabel":"التوبة: 50","question":"لماذا اختير ﴿تصبك﴾ للحسنة والمصيبة معًا؟","answer":"الإصابة أعم من المس؛ إذ تستعمل في المحسوس والمعنوي، ولذلك صلحت للحسنة والمصيبة، وأفادت بلوغ أثر كل منهما إلى المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص359–361.","url":""}]},{"id":"s9-301","number":301,"surah":9,"verses":[50],"verseLabel":"التوبة: 50","question":"لماذا نكرت ﴿حسنة﴾ و﴿مصيبة﴾؟","answer":"نُكرتا ليفيد الشرط أن أي حسنة، ولو قليلة، تسوءهم، وأن أي مصيبة تقع يتخذونها موضع شماتة؛ فالتنكير للتعميم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص360–362.","url":""}]},{"id":"s9-302","number":302,"surah":9,"verses":[50],"verseLabel":"التوبة: 50","question":"ما دلالة قولهم: ﴿قد أخذنا أمرنا من قبل﴾؟","answer":"معناه أنهم يزعمون أنهم أخذوا حذرهم ودبروا أمرهم قبل وقوع المصيبة، فلم يخرجوا مع المؤمنين؛ وفيه إظهار عجبهم برأيهم وشماتتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص362–364.","url":""}]},{"id":"s9-303","number":303,"surah":9,"verses":[50],"verseLabel":"التوبة: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتولوا وهم فرحون﴾، فجمع التولي والفرح؟","answer":"التولي يصور انصرافهم عن مجلس المسلمين، والحال ﴿وهم فرحون﴾ تكشف الفرح الملازم لهم بالمصيبة؛ فجمع بين حركة الظاهر وخبث الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص364–365.","url":""}]},{"id":"s9-304","number":304,"surah":9,"verses":[51],"verseLabel":"التوبة: 51","question":"لماذا جاء الرد بالأمر: ﴿قل لن يصيبنا إلا ما كتب الله لنا﴾؟","answer":"جاء الأمر بـ﴿قل﴾ لتلقين المؤمنين الرد الذي يبطل شماتة المنافقين: لا يقع شيء خارج تقدير الله، وما قدره لعباده المؤمنين فمآله إلى الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص366–368.","url":""}]},{"id":"s9-305","number":305,"surah":9,"verses":[51],"verseLabel":"التوبة: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب الله لنا﴾ لا «علينا» مع احتمال المصيبة؟","answer":"قال ﴿لنا﴾ لأن ما يقدره الله للمؤمنين خير لهم في العاقبة، نصرًا أو شهادة وأجرًا؛ فالمصيبة في ظاهرها تنتهي إلى منفعة إيمانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص368–370.","url":""}]},{"id":"s9-306","number":306,"surah":9,"verses":[51],"verseLabel":"التوبة: 51","question":"لماذا وصف الله بأنه ﴿مولانا﴾ في هذا المقام؟","answer":"﴿مولانا﴾ تفيد الولاية والنصرة والتدبير؛ فمن تولاه الله لم يجزع من تقديره ولم يركن إلى احتياط المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص369–371.","url":""}]},{"id":"s9-307","number":307,"surah":9,"verses":[51],"verseLabel":"التوبة: 51","question":"ما سرّ تقديم الجار والمجرور في ﴿وعلى الله فليتوكل المؤمنون﴾؟","answer":"تقديم ﴿على الله﴾ يفيد القصر: على الله وحده يعتمد المؤمنون، لا على عدة أو حذر مستقل عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص371–372.","url":""}]},{"id":"s9-308","number":308,"surah":9,"verses":[52],"verseLabel":"التوبة: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿هل تربصون بنا إلا إحدى الحسنيين﴾، فسمّى النصر والشهادة حسنيين؟","answer":"النصر حسن لما فيه من الظفر، والشهادة حسنى لما فيها من الثواب؛ فالمؤمن بين عاقبتين محبوبتين لا موضع فيهما لشماتة المنافق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص373–376.","url":""}]},{"id":"s9-309","number":309,"surah":9,"verses":[52],"verseLabel":"التوبة: 52","question":"لماذا أفرد ﴿إحدى﴾ وثنّى المعنى في ﴿الحسنيين﴾؟","answer":"﴿إحدى﴾ مفردة لأنها واحدة من نتيجتين، و﴿الحسنيين﴾ مثنى لأنها تحدد المجموع الذي تقع منه الواحدة: النصر أو الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص375–378.","url":""}]},{"id":"s9-310","number":310,"surah":9,"verses":[52],"verseLabel":"التوبة: 52","question":"لماذا قابل انتظار المؤمنين إحدى الحسنيين بانتظار عذاب المنافقين؟","answer":"المؤمن ينتظر خيرًا في كلتا الحالين، أما المنافق فينتظره عذاب من الله أو عقوبة بأيدي المؤمنين؛ فالمقابلة تقلب التربص على صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص377–380.","url":""}]},{"id":"s9-311","number":311,"surah":9,"verses":[52],"verseLabel":"التوبة: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿بعذاب من عنده أو بأيدينا﴾؟","answer":"﴿من عنده﴾ يشمل ما ينزله الله بلا مباشرة المؤمنين، و﴿بأيدينا﴾ ما يجريه من القتل والأسر على أيديهم؛ فاستوعب طريقي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص379–382.","url":""}]},{"id":"s9-312","number":312,"surah":9,"verses":[52],"verseLabel":"التوبة: 52","question":"لماذا ختم بقوله: ﴿فتربصوا إنا معكم متربصون﴾؟","answer":"الأمر للتهديد لا للإباحة؛ أي استمروا في انتظاركم، فنحن ننتظر لكم إحدى العقوبتين، وستظهر عاقبة كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص381–386.","url":""}]},{"id":"s9-313","number":313,"surah":9,"verses":[53],"verseLabel":"التوبة: 53","question":"لماذا أمرهم بالإنفاق طوعًا أو كرهًا ثم حكم بأنه لن يتقبل منهم؟","answer":"الأمر للتسوية والتهديد: أنفقوا مختارين أو مكرهين، فلن ينفعكم الإنفاق؛ لأن فقد الإيمان أفسد أساس القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص387–390.","url":""}]},{"id":"s9-314","number":314,"surah":9,"verses":[53],"verseLabel":"التوبة: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿أنفقوا طوعًا أو كرهًا﴾ بصيغة الأمر؟","answer":"صيغة الأمر ليست طلبًا مقصودًا للإنفاق، بل تفيد التسوية بين حالتي الطوع والكره في عدم القبول، وفيها إهانة وقطع لأطماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص389–392.","url":""}]},{"id":"s9-315","number":315,"surah":9,"verses":[53],"verseLabel":"التوبة: 53","question":"لماذا بُني ﴿لن يتقبل منكم﴾ للمجهول؟","answer":"حذف الفاعل لأن المقصود إبراز النتيجة، وهي انتفاء القبول قطعًا، لا بيان مَن يتقبل؛ والفاعل معلوم من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص391–394.","url":""}]},{"id":"s9-316","number":316,"surah":9,"verses":[53],"verseLabel":"التوبة: 53","question":"لماذا علل عدم القبول بقوله: ﴿إنكم كنتم قومًا فاسقين﴾؟","answer":"الفسق خروج عن طاعة الله، وهو وصف جامع يبين أن رد النفقة ناشئ من حال راسخة، لا من خلل عارض في عمل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص393–395.","url":""}]},{"id":"s9-317","number":317,"surah":9,"verses":[54],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وما منعهم أن تقبل منهم نفقاتهم إلا أنهم كفروا﴾؟","answer":"أسلوب القصر بـ﴿ما... إلا﴾ يحصر مانع القبول في كفرهم بالله ورسوله، ثم تفصل الآية مظاهر هذا الكفر في الصلاة والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص396–399.","url":""}]},{"id":"s9-318","number":318,"surah":9,"verses":[54],"verseLabel":"التوبة: 54","question":"لماذا أعيد نفي القبول بعد الآية السابقة؟","answer":"الآية السابقة قررت الحكم إجمالًا، وهذه بينت سببه وعلاماته؛ فالإعادة تفصيل وتعليل بعد إجمال، وليست تكرارًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص398–400.","url":""}]},{"id":"s9-319","number":319,"surah":9,"verses":[54],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يأتون الصلاة إلا وهم كسالى﴾، دون أن يقال: «لا يصلون إلا بكسل»؟","answer":"﴿يأتون الصلاة﴾ يصور مجيئهم إلى أدائها في جماعة مع ثقل ونفور، والجملة الحالية ﴿وهم كسالى﴾ تجعل الكسل هيئة ملازمة لهم عند الإتيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص399–401.","url":""}]},{"id":"s9-320","number":320,"surah":9,"verses":[54],"verseLabel":"التوبة: 54","question":"لماذا جمع بين الكسل في الصلاة وكراهة الإنفاق؟","answer":"جمعهما لأن الصلاة والإنفاق أبرز العبادات البدنية والمالية؛ وكسلهم في الأولى وكراهتهم للثانية يكشفان خلو العمل من الإيمان والإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص400–402.","url":""}]},{"id":"s9-321","number":321,"surah":9,"verses":[54],"verseLabel":"التوبة: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينفقون إلا وهم كارهون﴾ بجملة اسمية حالية؟","answer":"الجملة الاسمية الحالية تصور الكراهة وصفًا ثابتًا مصاحبًا لكل إنفاق منهم، لا خاطرًا عابرًا يقع مرة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص402–403.","url":""}]},{"id":"s9-322","number":322,"surah":9,"verses":[55],"verseLabel":"التوبة: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعجبك أموالهم ولا أولادهم﴾ مع أن المال والولد نعم؟","answer":"النهي عن الإعجاب ليس لأنهما ليسا نعمة في ذاتهما، بل لأنهما صارا في حق المنافقين وسيلة تعب وعقوبة في الدنيا ثم يموتون على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص404–407.","url":""}]},{"id":"s9-323","number":323,"surah":9,"verses":[55],"verseLabel":"التوبة: 55","question":"ما سرّ تقديم الأموال على الأولاد؟","answer":"قُدمت الأموال لأنها أظهر أسباب الإعجاب، ولأن تعلقهم بها وكلفة جمعها وحفظها وإنفاقها مصدر مباشر لعذابهم، ثم عطف الأولاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص406–409.","url":""}]},{"id":"s9-324","number":324,"surah":9,"verses":[55],"verseLabel":"التوبة: 55","question":"ما وجه كون أموال المنافقين وأولادهم عذابًا لهم في الحياة الدنيا؟","answer":"عذابهم بهما يكون بما يلاقونه في تحصيلهما وحفظهما والخوف عليهما، وبما يكلفون من الإنفاق مع الكراهة، وبما يصيبهم فيهما من الآفات والأحزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص408–411.","url":""}]},{"id":"s9-325","number":325,"surah":9,"verses":[55],"verseLabel":"التوبة: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿وتزهق أنفسهم﴾، دون أن يقال: «ويموتوا»؟","answer":"الزهوق خروج النفس بمشقة وسرعة، وهو أبلغ تصويرًا من مجرد الموت؛ ويشعر بأن أرواحهم تفارقهم وهم على الكفر والحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص410–413.","url":""}]},{"id":"s9-326","number":326,"surah":9,"verses":[55],"verseLabel":"التوبة: 55","question":"لماذا ختم بـ﴿وهم كافرون﴾؟","answer":"الحال ﴿وهم كافرون﴾ تبين أخطر مآل للعذاب الدنيوي: أن تنتهي حياتهم من غير توبة، فيتصل عذاب الدنيا بعذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص412–415.","url":""}]},{"id":"s9-327","number":327,"surah":9,"verses":[56],"verseLabel":"التوبة: 56","question":"لماذا يحلف المنافقون: ﴿إنهم لمنكم﴾ ثم ينفي الله ذلك؟","answer":"يحلفون طلبًا للسلامة واتقاءً لانكشافهم، فنفى الله انتسابهم الحقيقي إلى المؤمنين؛ إذ جمعتهم الظواهر وفرقتهم العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص416–418.","url":""}]},{"id":"s9-328","number":328,"surah":9,"verses":[56],"verseLabel":"التوبة: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكنهم قوم يفرقون﴾، دون أن يقال: «يخافون»؟","answer":"﴿يفرقون﴾ أبلغ من مطلق الخوف؛ فهو خوف شديد مستمر يحملهم على الحلف والتستر والهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص418–421.","url":""}]},{"id":"s9-329","number":329,"surah":9,"verses":[56],"verseLabel":"التوبة: 56","question":"لماذا وصفهم بـ﴿قوم﴾ في مقام الذم؟","answer":"التعبير بـ﴿قوم﴾ يشعر بأن الفرق صار سجية جامعة لهم حتى كأنهم جماعة عرفت به، وفيه تثبيت لوصف الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص420–423.","url":""}]},{"id":"s9-330","number":330,"surah":9,"verses":[57],"verseLabel":"التوبة: 57","question":"لماذا عدّد الملجأ والمغارات والمدخل؟","answer":"عُددت لتصوير شدة نفورهم واستقصاء كل مكان يمكن أن يحجبهم: ملجأ يحمي، أو مغارات تستر، أو مدخل ينفذون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص424–426.","url":""}]},{"id":"s9-331","number":331,"surah":9,"verses":[57],"verseLabel":"التوبة: 57","question":"ما الفرق التصويري بين ﴿ملجأ﴾ و﴿مغارات﴾ و﴿مدخلًا﴾؟","answer":"الملجأ مكان يتحصنون به، والمغارات تجاويف الجبال، والمدخل موضع ضيق ينفذون فيه أو سرداب؛ فتتنوع الصورة من الاحتماء إلى الاختباء والانحشار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص425–428.","url":""}]},{"id":"s9-332","number":332,"surah":9,"verses":[57],"verseLabel":"التوبة: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿لولوا إليه وهم يجمحون﴾؟","answer":"﴿لولوا إليه﴾ تفيد سرعة الانصراف نحوه، و﴿يجمحون﴾ تصور اندفاعًا لا يملكون رده كجموح الدابة؛ مبالغة في فرارهم من المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص427–430.","url":""}]},{"id":"s9-333","number":333,"surah":9,"verses":[58],"verseLabel":"التوبة: 58","question":"لماذا عبّر عن الطعن في قسمة الصدقات بقوله: ﴿يلمزك﴾؟","answer":"اللمز طعن وعيب في خفاء أو بمواجهة يسيرة؛ فاختياره يصور اعتراضهم الخبيث على النبي ﷺ في قسمة الصدقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص431–433.","url":""}]},{"id":"s9-334","number":334,"surah":9,"verses":[58],"verseLabel":"التوبة: 58","question":"لماذا كرر الشرطين: ﴿فإن أعطوا منها رضوا وإن لم يعطوا منها إذا هم يسخطون﴾؟","answer":"فصل الشرطان ميزانهم النفعي: الرضا تابع للأخذ، والسخط تابع للحرمان؛ فلا يحكمهم حق ولا عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص433–436.","url":""}]},{"id":"s9-335","number":335,"surah":9,"verses":[58],"verseLabel":"التوبة: 58","question":"لماذا جاءت المفاجأة بـ﴿إذا هم يسخطون﴾؟","answer":"﴿إذا﴾ الفجائية تصور سرعة انقلابهم إلى السخط بمجرد عدم العطاء، من غير تروٍّ أو نظر في حكمة القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص435–438.","url":""}]},{"id":"s9-336","number":336,"surah":9,"verses":[58],"verseLabel":"التوبة: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿هم يسخطون﴾ بالجملة الاسمية؟","answer":"الجملة الاسمية تثبت السخط وصفًا مستقرًا فيهم، وضمير الفصل أو الابتداء يبرز أنهم أهل السخط عند الحرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص437–439.","url":""}]},{"id":"s9-337","number":337,"surah":9,"verses":[59],"verseLabel":"التوبة: 59","question":"لماذا جاء الجواب الافتراضي: ﴿ولو أنهم رضوا ما آتاهم الله ورسوله﴾؟","answer":"عرضت الآية الحال التي كان ينبغي أن يكونوا عليها: الرضا بالقسمة والتوكل على الله والرغبة إليه، وفي ذلك تقريع على نقيض فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص440–442.","url":""}]},{"id":"s9-338","number":338,"surah":9,"verses":[59],"verseLabel":"التوبة: 59","question":"لماذا نسب الإيتاء إلى الله ورسوله، ثم قال: ﴿وقالوا حسبنا الله﴾؟","answer":"نسب الإيتاء إلى الله ورسوله لأن الله هو المقدِّر والرسول ﷺ هو المباشر للقسمة بأمره، أما الكفاية والفضل فمن الله وحده فقالوا: ﴿حسبنا الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص442–445.","url":""}]},{"id":"s9-339","number":339,"surah":9,"verses":[59],"verseLabel":"التوبة: 59","question":"لماذا تكرر ذكر الله في الآية ولم يكتف بالضمائر؟","answer":"تكرار الاسم الجليل يربي المعاني على مصدرها: الإيتاء والحسب والفضل والرغبة كلها متعلقة بالله، وفي إظهاره تعظيم وتوكيد لا يؤديه الضمير مثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص444–446.","url":""}]},{"id":"s9-340","number":340,"surah":9,"verses":[59],"verseLabel":"التوبة: 59","question":"لماذا جمعوا بين ﴿حسبنا الله﴾ و﴿إنا إلى الله راغبون﴾؟","answer":"﴿حسبنا الله﴾ تفويض وثقة بالكفاية في الحاضر، و﴿إنا إلى الله راغبون﴾ توجه إليه فيما يستقبل؛ فجمعا التوكل والطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص446–447.","url":""}]},{"id":"s9-341","number":341,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"لماذا افتتحت آية المصارف بـ﴿إنما الصدقات﴾؟","answer":"﴿إنما﴾ تقصر الصدقات على الأصناف المذكورة، فترد اعتراض من يطلبها لغير استحقاق وتبين أن قسمتها حكم شرعي لا هوى شخصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص448–450.","url":""}]},{"id":"s9-342","number":342,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"لماذا سُمّيت الزكاة هنا ﴿الصدقات﴾؟","answer":"سميت صدقات لأن إخراجها دليل على صدق إيمان صاحبها وطاعته، ولأن اللفظ يلائم مقابلة المنافقين الذين ينفقون كارهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص450–452.","url":""}]},{"id":"s9-343","number":343,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"لماذا بدأ بالفقراء ثم المساكين؟","answer":"بدأ بالفقراء لشدة حاجتهم أو لأنهم الأصل الأسبق في استحقاق المعونة، ثم عطف المساكين ممن لهم حاجة دونهم أو تقاربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص452–454.","url":""}]},{"id":"s9-344","number":344,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"ما سرّ التعبير في قوله تعالى في الأصناف الأربعة الأولى باللام، ثم قال: ﴿وفي الرقاب والغارمين وفي سبيل الله﴾ بـ﴿في﴾؟","answer":"اللام في الأصناف الأولى تفيد تمليك المال لهم، و﴿في﴾ تفيد صرفه في جهة فك الرقاب وقضاء الدين وسبيل الله، فروعيت طبيعة الاستحقاق والصرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص454–456.","url":""}]},{"id":"s9-345","number":345,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿المؤلفة قلوبهم﴾ بالبناء للمجهول؟","answer":"حذف فاعل التأليف لأن المقصود قلوب يراد استمالتها إلى الإسلام أو تثبيتها عليه، لا تعيين المؤلف؛ وفيه إبراز تحول القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص456–458.","url":""}]},{"id":"s9-346","number":346,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"لماذا أفرد ﴿ابن السبيل﴾ مع جمع بقية الأصناف؟","answer":"﴿ابن السبيل﴾ اسم جنس يصدق على كل مسافر انقطع به الطريق، وإفراده يرسم شدة ملازمته للسبيل كأنه ابنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص457–458.","url":""}]},{"id":"s9-347","number":347,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"لماذا ختم تعداد المصارف بقوله: ﴿فريضة من الله﴾؟","answer":"﴿فريضة من الله﴾ تؤكد أن تحديد المصارف حكم واجب صادر من الله، فلا مدخل فيه لأهواء المعترضين أو اجتهاد في نقلها إلى غير أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص458.","url":""}]},{"id":"s9-348","number":348,"surah":9,"verses":[60],"verseLabel":"التوبة: 60","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بأحوال المستحقين وحاجاتهم، و﴿حكيم﴾ في توزيع المال بينهم؛ فالخاتمة تعلل دقة القسمة وعدلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص458.","url":""}]},{"id":"s9-349","number":349,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"لماذا عبّر عن إيذاء النبي ﷺ بقوله: ﴿ومنهم الذين يؤذون النبي﴾ دون ذكر نوع الأذى؟","answer":"أُطلق الأذى ليشمل أقوالهم وأفعالهم كلها، وليدل على تجدد أذاهم، ثم خُص من أقوالهم طعنهم فيه بقولهم: ﴿هو أذن﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص459–462.","url":""}]},{"id":"s9-350","number":350,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"لماذا وصفه المنافقون بقولهم: ﴿هو أذن﴾؟","answer":"قصدوا أنه يسمع كل ما يقال ويصدقه، فحولوا خلقه في الحلم وحسن الاستماع إلى مطعن يتهمونه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص461–464.","url":""}]},{"id":"s9-351","number":351,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"لماذا جاء الرد: ﴿قل أذن خير لكم﴾، فأبقى اللفظ نفسه؟","answer":"أبقى لفظهم وقيده بالخير، فقلب الذم مدحًا: هو أذن فيما ينفعكم، يسمع الوحي والحق ويقبل منكم ظاهر الاعتذار رحمة وحلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص463–466.","url":""}]},{"id":"s9-352","number":352,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"لماذا أضيفت ﴿أذن﴾ إلى ﴿خير﴾؟","answer":"إضافة ﴿أذن﴾ إلى ﴿خير﴾ تخصص سماعه بما هو خير لهم، وتنفي زعمهم أنه يقبل كل باطل بلا تمييز.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص465–467.","url":""}]},{"id":"s9-353","number":353,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"لماذا فرّق بين ﴿يؤمن بالله﴾ و﴿يؤمن للمؤمنين﴾؟","answer":"عدي الإيمان بالله بالباء لأنه تصديق، وعدي الإيمان للمؤمنين باللام بمعنى يصدقهم ويطمئن إلى صدقهم؛ ففرّق النظم بين متعلقين ومعنيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص466–469.","url":""}]},{"id":"s9-354","number":354,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿ورحمة للذين آمنوا منكم﴾، فقيد الرحمة بالمؤمنين؟","answer":"هو رحمة للمؤمنين بما جاءهم به من الهدى وبحلمه ورأفته، أما من أصر على النفاق والأذى فلا ينتفع بهذه الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص468–470.","url":""}]},{"id":"s9-355","number":355,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"لماذا أعاد الاسم الموصول: ﴿والذين يؤذون رسول الله﴾ بعد قوله ﴿الذين يؤذون النبي﴾؟","answer":"أعيد الموصول لاستئناف حكم عام في كل من يؤذي الرسول ﷺ، وليترتب عليه الوعيد مستقلًا بعد الرد على مقالتهم الخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص470–472.","url":""}]},{"id":"s9-356","number":356,"surah":9,"verses":[61],"verseLabel":"التوبة: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿لهم عذاب أليم﴾ بدل «سيعذبهم الله»؟","answer":"الجملة الاسمية مع تقديم ﴿لهم﴾ تثبت اختصاصهم بالعذاب واستقراره لهم، ووصفه بالأليم يجانس الأذى الذي ألحقوه بالرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص472–473.","url":""}]},{"id":"s9-357","number":357,"surah":9,"verses":[62],"verseLabel":"التوبة: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون بالله لكم ليرضوكم﴾، فجعل غاية الحلف رضا المؤمنين؟","answer":"يبادرون بالحلف للمؤمنين ليستروا أذاهم ويحفظوا مكانهم بينهم؛ فكشف النظم أنهم يقدمون رضا الناس على رضا الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص474–477.","url":""}]},{"id":"s9-358","number":358,"surah":9,"verses":[62],"verseLabel":"التوبة: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿والله ورسوله أحق أن يرضوه﴾، فأفرد الضمير مع ذكر اثنين؟","answer":"أُفرد الضمير لأن رضا الرسول ﷺ تابع لرضا الله، وإرضاء أحدهما لا ينفصل عن الآخر؛ فهما في هذا الحكم جهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص476–480.","url":""}]},{"id":"s9-359","number":359,"surah":9,"verses":[62],"verseLabel":"التوبة: 62","question":"ما سرّ تقديم اسم الله ثم الرسول في ﴿والله ورسوله أحق﴾؟","answer":"قُدم اسم الله لأنه أصل الاستحقاق، ثم ذكر الرسول ﷺ لأن إرضاءه من إرضاء الله وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص479–482.","url":""}]},{"id":"s9-360","number":360,"surah":9,"verses":[62],"verseLabel":"التوبة: 62","question":"لماذا استعمل ﴿أحق﴾ مع أن إرضاء الله ورسوله واجب لا مجرد أولى؟","answer":"﴿أحق﴾ جاءت في مقابلة جعلهم رضا المؤمنين غايتهم؛ أي إن كان ثمة من يطلب رضاه فالله ورسوله أولى وحدهما، واللفظ يتضمن وجوب ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص481–484.","url":""}]},{"id":"s9-361","number":361,"surah":9,"verses":[62],"verseLabel":"التوبة: 62","question":"لماذا خُتم بـ﴿إن كانوا مؤمنين﴾؟","answer":"الشرط يفضح دعوى الإيمان: إن كانوا مؤمنين حقًا لقدموا رضا الله ورسوله، أما صنيعهم فدليل على خلاف ما يظهرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص484–488.","url":""}]},{"id":"s9-362","number":362,"surah":9,"verses":[63],"verseLabel":"التوبة: 63","question":"لماذا افتتحت الآية بـ﴿ألم يعلموا﴾ مع أن المنافقين يخفون كفرهم؟","answer":"الاستفهام للتوبيخ والتقرير؛ وعلمهم بما توعد الله به من المحادة حجة عليهم، وإن أظهروا الإيمان وأبطنوا الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص489–492.","url":""}]},{"id":"s9-363","number":363,"surah":9,"verses":[63],"verseLabel":"التوبة: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿من يحادد الله ورسوله﴾؟","answer":"المحادة اتخاذ حد وجانب في مقابلة حد الله ورسوله؛ فصورت مخالفتهم عداوة ومشاقة صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص491–494.","url":""}]},{"id":"s9-364","number":364,"surah":9,"verses":[63],"verseLabel":"التوبة: 63","question":"لماذا أفرد الضمير في ﴿فأن له نار جهنم﴾ بعد ذكر الله ورسوله؟","answer":"الضمير يعود إلى ﴿من﴾، أي لذلك المحاد نار جهنم؛ واتحاد طاعة الرسول ﷺ بطاعة الله يجعل محادتهما حكمًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص493–496.","url":""}]},{"id":"s9-365","number":365,"surah":9,"verses":[63],"verseLabel":"التوبة: 63","question":"لماذا جمع بين ﴿خالدًا فيها﴾ و﴿ذلك الخزي العظيم﴾؟","answer":"﴿خالدًا فيها﴾ يبين دوام العذاب، و﴿ذلك الخزي العظيم﴾ يجمع إلى الألم الهوان والفضيحة؛ فاستوفى نوعي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص496–499.","url":""}]},{"id":"s9-366","number":366,"surah":9,"verses":[63],"verseLabel":"التوبة: 63","question":"لماذا أشار إلى العذاب بالبعيد: ﴿ذلك الخزي العظيم﴾؟","answer":"اسم الإشارة للبعيد يفخم شأن الخزي ويهول منزلته، ثم أكده بوصفه ﴿العظيم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص499–503.","url":""}]},{"id":"s9-367","number":367,"surah":9,"verses":[64],"verseLabel":"التوبة: 64","question":"كيف يحذر المنافقون أن تنزل سورة تكشفهم مع أنهم لا يصدقون الوحي؟","answer":"حذرهم ناشئ من علمهم بصدق الرسول ﷺ وخوفهم انكشاف أسرارهم، وإن لم يكن إيمانهم بالوحي إيمان تصديق وانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص504–507.","url":""}]},{"id":"s9-368","number":368,"surah":9,"verses":[64],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿يحذر المنافقون أن تنزل عليهم سورة﴾، مع أن السورة تنزل على النبي؟","answer":"﴿عليهم﴾ لأنها وإن نزلت على النبي ﷺ كانت في شأنهم وكاشفة لأحوالهم، فكان وقعها وضررها عائدًا عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص506–509.","url":""}]},{"id":"s9-369","number":369,"surah":9,"verses":[64],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿تنبئهم بما في قلوبهم﴾، فجعل السورة مخبرة للمنافقين أنفسهم؟","answer":"إخبار السورة بما في قلوبهم يبلغهم كشف أسرارهم ويفضح بعضهم لبعض وللمؤمنين؛ فنسب الإنباء إليها لأنها الواسطة المتلوة في بيان حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص508–512.","url":""}]},{"id":"s9-370","number":370,"surah":9,"verses":[64],"verseLabel":"التوبة: 64","question":"لماذا أُمر النبي أن يقول لهم: ﴿استهزئوا﴾؟","answer":"الأمر للتهديد والتعجيز، لا للإذن؛ أي استمروا في استهزائكم فالله سيظهر ما تخافون ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص511–514.","url":""}]},{"id":"s9-371","number":371,"surah":9,"verses":[64],"verseLabel":"التوبة: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله مخرج ما تحذرون﴾، وصوّر السر كشيء يُخرج؟","answer":"صور ما أخفوه في القلوب شيئًا محبوسًا يخرجه الله إلى العلن، وفيه تأكيد أن كتمانهم لا يمنع افتضاحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص513–517.","url":""}]},{"id":"s9-372","number":372,"surah":9,"verses":[64],"verseLabel":"التوبة: 64","question":"لماذا اختير اسم الفاعل ﴿مخرج﴾ لا الفعل «سيخرج»؟","answer":"اسم الفاعل يدل على ثبوت الوعد وتحققه واستمرار القدرة عليه، فكأن إخراج أسرارهم وصف قائم لا أمر محتمل في المستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص516–522.","url":""}]},{"id":"s9-373","number":373,"surah":9,"verses":[65],"verseLabel":"التوبة: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿ولئن سألتهم ليقولن إنما كنا نخوض ونلعب﴾؟","answer":"اللام في الشرط والجواب تؤكد أن سؤالهم سيكشف عذرهم الجاهز: حصروا فعلهم في خوض ولعب لينفوا قصد الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص523–525.","url":""}]},{"id":"s9-374","number":374,"surah":9,"verses":[65],"verseLabel":"التوبة: 65","question":"لماذا عبّروا عن استهزائهم بـ﴿نخوض ونلعب﴾؟","answer":"الخوض دخول في الكلام الباطل بلا ضبط، واللعب فعل بلا جد؛ فحاولا تصوير استهزائهما حديثًا عابرًا لا مؤاخذة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص525–527.","url":""}]},{"id":"s9-375","number":375,"surah":9,"verses":[65],"verseLabel":"التوبة: 65","question":"لماذا جاء الرد بسؤال ثلاثي: ﴿أبالله وآياته ورسوله كنتم تستهزئون﴾؟","answer":"عدد المتعلقات ليبين عظم الجريمة: الاستهزاء تناول الله وآياته ورسوله، وكل واحد منها كاف في بطلان عذرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص527–529.","url":""}]},{"id":"s9-376","number":376,"surah":9,"verses":[65],"verseLabel":"التوبة: 65","question":"ما سرّ تقديم اسم الله على الآيات والرسول؟","answer":"قُدم اسم الله لأنه أعظم ما تعلق به استهزاؤهم، ثم آياته الدالة عليه ورسوله المبلغ لها، على ترتيب الأصل والتبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص529–531.","url":""}]},{"id":"s9-377","number":377,"surah":9,"verses":[66],"verseLabel":"التوبة: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تعتذروا﴾ مع أنهم قدموا عذر اللعب؟","answer":"نُهوا عن الاعتذار لأن قولهم ﴿إنما كنا نخوض ونلعب﴾ لا يصلح عذرًا، بل هو إقرار بالفعل ومحاولة لتهوين جريمة لا يهونها اللعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص532–534.","url":""}]},{"id":"s9-378","number":378,"surah":9,"verses":[66],"verseLabel":"التوبة: 66","question":"ما وجه قوله تعالى: ﴿قد كفرتم بعد إيمانكم﴾ مع وصفهم قبل ذلك بالمنافقين؟","answer":"المعنى أن كلمة الكفر أظهرت ما يناقض إيمانهم المعلن، أو أنهم انتقلوا إلى كفر صريح بعد إظهار الإيمان؛ وليس فيه إثبات إيمان صحيح مستقر لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص534–537.","url":""}]},{"id":"s9-379","number":379,"surah":9,"verses":[66],"verseLabel":"التوبة: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿إن نعف عن طائفة منكم نعذب طائفة﴾؟","answer":"قسمتهم الآية إلى طائفتين بحسب المآل: من قُبل عذره أو تاب فعفي عنه، ومن أصر على النفاق والإجرام فعذب؛ فلا يتساوى الجميع في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص536–539.","url":""}]},{"id":"s9-380","number":380,"surah":9,"verses":[66],"verseLabel":"التوبة: 66","question":"لماذا بُني ﴿نعف﴾ و﴿نعذب﴾ بضمير العظمة؟","answer":"ضمير العظمة في ﴿نعف﴾ و﴿نعذب﴾ يبرز كمال القدرة والسلطان في العفو والعقوبة، وأن أمر الفريقين إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص538–540.","url":""}]},{"id":"s9-381","number":381,"surah":9,"verses":[66],"verseLabel":"التوبة: 66","question":"لماذا علل التعذيب بقوله: ﴿بأنهم كانوا مجرمين﴾ لا «مستهزئين»؟","answer":"الإجرام أعم ويكشف رسوخ الذنب وتعديه؛ فاستهزاؤهم ثم اعتذارهم الكاذب مظهر من حال إجرامية مستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص540–542.","url":""}]},{"id":"s9-382","number":382,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿المنافقون والمنافقات بعضهم من بعض﴾، وقال في المؤمنين: ﴿بعضهم أولياء بعض﴾؟","answer":"﴿بعضهم من بعض﴾ تفيد تشابه المنافقين وتولد بعضهم من طينة بعض في الشر، من غير ولاية نصرة صادقة؛ أما المؤمنون فجامعهم التناصر والموالاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص543–547.","url":""}]},{"id":"s9-383","number":383,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"ما سرّ تقديم المنافقون على المنافقات؟","answer":"قُدم المنافقون جريًا على الغالب في توجيه الخطاب وظهور أثر الرجال في الحركة، ثم ذكرت المنافقات لإحاطة الحكم بالجنسين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص545–548.","url":""}]},{"id":"s9-384","number":384,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"ما سرّ تقديم الأمر بالمنكر على النهي عن المعروف؟","answer":"قُدم الأمر بالمنكر لأنه فعل إيجابي في نشر الفساد، ثم عطف منع المعروف؛ فجمعوا إفساد الموجود وصد الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص547–550.","url":""}]},{"id":"s9-385","number":385,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"ما الصورة في قوله: ﴿ويقبضون أيديهم﴾؟","answer":"كناية عن البخل ومنع الإنفاق والمعونة؛ فصوّر أيديهم مقبوضة لا تمتد إلى خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص549–552.","url":""}]},{"id":"s9-386","number":386,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"ما دلالة قوله تعالى: ﴿نسوا الله فنسيهم﴾، وهل يوصف الله بالنسيان؟","answer":"ليس النسيان هنا ذهولًا؛ بل تركوا ذكر الله وطاعته، فعاملهم معاملة المنسي بتركهم من رحمته وتوفيقه، جزاءً وفاقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص551–554.","url":""}]},{"id":"s9-387","number":387,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"لماذا رتب نسيان الله لهم بالفاء على نسيانهم؟","answer":"الفاء تفيد ترتيب الجزاء على العمل وتعقيبه: لما تركوا طاعة الله جازاهم بتركهم من فضله وتوفيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص553–555.","url":""}]},{"id":"s9-388","number":388,"surah":9,"verses":[67],"verseLabel":"التوبة: 67","question":"لماذا ختم بـ﴿إن المنافقين هم الفاسقون﴾؟","answer":"أكد الحكم بـ﴿إن﴾ وضمير الفصل ﴿هم﴾ وقصر الفسق عليهم للمبالغة؛ لأن النفاق جمع وجوه الخروج عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص555–558.","url":""}]},{"id":"s9-389","number":389,"surah":9,"verses":[68],"verseLabel":"التوبة: 68","question":"لماذا جمع في الوعيد المنافقين والمنافقات والكفار؟","answer":"جمعهم لاشتراكهم في الكفر والمصير، مع التصريح بالذكور والإناث من المنافقين حتى يعم الوعيد جميع أصنافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص559–561.","url":""}]},{"id":"s9-390","number":390,"surah":9,"verses":[68],"verseLabel":"التوبة: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿نار جهنم خالدين فيها هي حسبهم﴾؟","answer":"﴿خالدين فيها﴾ يقرر الدوام، و﴿هي حسبهم﴾ تفيد أن جهنم وحدها كافية في جزائهم فلا يحتاجون معها إلى عذاب آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص561–563.","url":""}]},{"id":"s9-391","number":391,"surah":9,"verses":[68],"verseLabel":"التوبة: 68","question":"لماذا جمع بين النار ولعنة الله والعذاب المقيم؟","answer":"النار عذاب الأجساد، واللعنة إبعاد من رحمة الله، والعذاب المقيم يؤكد ملازمة الجزاء ودوامه؛ فجمع الألم والحرمان والاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص563–565.","url":""}]},{"id":"s9-392","number":392,"surah":9,"verses":[68],"verseLabel":"التوبة: 68","question":"لماذا وصف العذاب بأنه ﴿مقيم﴾ لا «دائم»؟","answer":"﴿مقيم﴾ يصور العذاب ثابتًا ملازمًا لا يبرح صاحبه، فكأنه مقيم معه؛ وهو أبلغ تصويرًا من الإخبار المجرد بالدوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص565–568.","url":""}]},{"id":"s9-393","number":393,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"لماذا شُبّه المنافقون بمن قبلهم قبل تفصيل أوجه الشبه؟","answer":"قدم التشبيه الإجمالي لاستحضار سنة الأمم قبلهم وتحذيرهم من المصير نفسه، ثم فصل وجوه المشابهة في القوة والمتاع والخوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص569–572.","url":""}]},{"id":"s9-394","number":394,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"لماذا عدد القوة وكثرة الأموال والأولاد؟","answer":"عددها لأنها أبرز أسباب اغترار الأمم: قوة الأبدان والسلطان، وسعة المال، وكثرة الأعوان والذرية؛ ولم تمنع عنهم العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص571–574.","url":""}]},{"id":"s9-395","number":395,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستمتعوا بخلاقهم فاستمتعتم بخلاقكم﴾؟","answer":"تكرار العبارة يطابق بين فعل السابقين واللاحقين: تمتع كل فريق بنصيبه العاجل حتى شغله عن الآخرة، فاستحقوا مآلًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص573–577.","url":""}]},{"id":"s9-396","number":396,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"ما معنى ﴿خلاقهم﴾، ولماذا اختير بدل «نصيبهم»؟","answer":"الخلاق هو النصيب المقدر للمرء، ويكثر استعماله في نصيب الخير؛ واختياره هنا يلمح إلى أنهم استنفدوا نصيبهم في متاع الدنيا فلم يبق لهم في الآخرة نصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص575–578.","url":""}]},{"id":"s9-397","number":397,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"لماذا كرر ﴿كما استمتع الذين من قبلكم بخلاقهم﴾ بعد وضوح التشبيه؟","answer":"كرر الاستمتاع لتأكيد مماثلة اللاحقين للسابقين في الاغترار بنصيب الدنيا، مع بيان أن من قبلهم كانوا أشد قوة وأكثر مالًا وولدًا فلم تغن عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص577–580.","url":""}]},{"id":"s9-398","number":398,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وخضتم كالذي خاضوا﴾، فأفرد ﴿الذي﴾؟","answer":"﴿الذي﴾ هنا مصدرية أو بمعنى الخوض الذي خاضوه؛ فالإفراد لأن المراد نوع الفعل لا جماعة الخائضين، أي خضتم كخوضهم في الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص579–582.","url":""}]},{"id":"s9-399","number":399,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"لماذا جمع بين حبوط الأعمال والخسران؟","answer":"حبوط الأعمال يبين بطلان ما عملوه وذهاب ثمرته، والخسران يبين ما عاد على ذواتهم من فقد الخير واستحقاق العقاب؛ فجمع خسارة العمل والعامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص582–586.","url":""}]},{"id":"s9-400","number":400,"surah":9,"verses":[69],"verseLabel":"التوبة: 69","question":"لماذا كرر اسم الإشارة وضمير الفصل: ﴿أولئك حبطت... وأولئك هم الخاسرون﴾؟","answer":"تكرار ﴿أولئك﴾ يستأنف لكل نتيجة حكمًا مستقلًا، و﴿هم﴾ تقوي نسبة الخسران إليهم وتفيد أنهم بلغوا غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص585–592.","url":""}]},{"id":"s9-401","number":401,"surah":9,"verses":[70],"verseLabel":"التوبة: 70","question":"لماذا سأل: ﴿ألم يأتهم نبأ الذين من قبلهم﴾ مع معرفتهم بأخبار بعضهم؟","answer":"الاستفهام للتقرير والتوبيخ؛ فالعبرة ليست بمجرد سماع الأخبار، بل بفهم دلالتها، وكأنها لم تأتهم لما لم ينتفعوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص593–596.","url":""}]},{"id":"s9-402","number":402,"surah":9,"verses":[70],"verseLabel":"التوبة: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿نبأ﴾ لا «خبر»؟","answer":"النبأ خبر عظيم ذو شأن وفائدة، فناسب أخبار الأمم وعقوباتها التي يجب أن تعتبر بها القلوب، بخلاف الخبر الذي قد يكون يسيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص595–598.","url":""}]},{"id":"s9-403","number":403,"surah":9,"verses":[70],"verseLabel":"التوبة: 70","question":"لماذا جمع أممًا متباعدة: قوم نوح وعاد وثمود وقوم إبراهيم وأصحاب مدين والمؤتفكات؟","answer":"جمعها لتعدد صور القوة والبيئات والأزمنة مع اتحاد سنة الله فيها: قامت عليهم الحجة بالبينات ثم أهلكوا لما كذبوا؛ وفي ذلك تحذير شامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص597–600.","url":""}]},{"id":"s9-404","number":404,"surah":9,"verses":[70],"verseLabel":"التوبة: 70","question":"لماذا سميت قرى لوط ﴿المؤتفكات﴾؟","answer":"سميت ﴿المؤتفكات﴾ لأنها ائتفكت، أي انقلبت بأهلها؛ فالاسم يستحضر هيئة العقوبة التي صارت علمًا على قراهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص599–602.","url":""}]},{"id":"s9-405","number":405,"surah":9,"verses":[70],"verseLabel":"التوبة: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿أتتهم رسلهم بالبينات﴾ بعد ذكر هلاكهم؟","answer":"ذكر مجيء الرسل بالبينات يقرر تمام الحجة قبل الهلاك، وينفي أن تكون العقوبة بلا إنذار أو بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص601–603.","url":""}]},{"id":"s9-406","number":406,"surah":9,"verses":[70],"verseLabel":"التوبة: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون﴾؟","answer":"نفت الصيغة المؤكدة إمكان الظلم عن الله، ثم أسندت ظلمهم إلى أنفسهم؛ لأنهم باختيار التكذيب جلبوا إليها العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص603–605.","url":""}]},{"id":"s9-407","number":407,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى في المؤمنين: ﴿بعضهم أولياء بعض﴾ بدل ﴿بعضهم من بعض﴾ الواردة في المنافقين؟","answer":"الولاية تتضمن المحبة والنصرة والتعاون على الخير، وهي رابطة المؤمنين؛ أما ﴿بعضهم من بعض﴾ في المنافقين فمجرد تشابه في الطبع والشر لا ولاء صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص606–608.","url":""}]},{"id":"s9-408","number":408,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"ما سرّ تقديم المؤمنين على المؤمنات ثم أشركهم جميعًا في الولاية؟","answer":"ذكر المؤمنين والمؤمنات ليشمل التكليف والجزاء الجنسين، وتقديم الرجال جار على الغالب، ثم جمع الجميع في ولاية إيمانية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص608–610.","url":""}]},{"id":"s9-409","number":409,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"ما سرّ تقديم الأمر بالمعروف على النهي عن المنكر، بعكس ترتيب المنافقين؟","answer":"المعروف أصل يقام ويُنشر، فقدم فعل الخير ثم منع ضده؛ وفي المنافقين قدم المنكر لأن شأنهم المبادرة إلى الإفساد والصد عن الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص609–612.","url":""}]},{"id":"s9-410","number":410,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"لماذا جمع الصلاة والزكاة بعد الأمر بالمعروف والنهي عن المنكر؟","answer":"الأمر والنهي إصلاح للمجتمع، ثم خص الصلاة والزكاة لأنهما عمادا صلاح الفرد في العبادة البدنية والمالية، ودليل صدق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص611–613.","url":""}]},{"id":"s9-411","number":411,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿ويطيعون الله ورسوله﴾ بعد تفصيل الأعمال؟","answer":"بعد ذكر أعمال ظاهرة مخصوصة جاء الوصف الجامع ﴿يطيعون الله ورسوله﴾ ليدخل فيه سائر الأوامر والنواهي، وليبين أن تلك الأعمال صادرة عن طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص613–615.","url":""}]},{"id":"s9-412","number":412,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك سيرحمهم الله﴾ بالسين؟","answer":"السين تفيد الوعد بالرحمة المستقبلة المتحققة، ولا سيما رحمة الآخرة؛ وفيها بشارة مرتبة على صفاتهم وأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص615–617.","url":""}]},{"id":"s9-413","number":413,"surah":9,"verses":[71],"verseLabel":"التوبة: 71","question":"لماذا ختم بـ﴿إن الله عزيز حكيم﴾ لا «غفور رحيم»؟","answer":"﴿عزيز﴾ قادر على نصر أوليائه وإنفاذ وعده، و﴿حكيم﴾ يضع الرحمة في أهلها؛ فالخاتمة تناسب الوعد بالتمكين والجزاء وفق الحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص617–618.","url":""}]},{"id":"s9-414","number":414,"surah":9,"verses":[72],"verseLabel":"التوبة: 72","question":"لماذا فصل جزاء المؤمنين بعد إجماله في ﴿سيرحمهم الله﴾؟","answer":"﴿سيرحمهم الله﴾ وعد مجمل، ثم فصلت الآية صور الرحمة من جنات ومساكن ورضوان، لزيادة التشويق وبيان عظم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص619–621.","url":""}]},{"id":"s9-415","number":415,"surah":9,"verses":[72],"verseLabel":"التوبة: 72","question":"لماذا جمع بين الجنات والمساكن الطيبة ورضوان الله؟","answer":"الجنات تجمع نعيم المكان، والمساكن الطيبة راحته واستقراره، والرضوان نعيم القرب والقبول؛ فجمع نعيم الحس والروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص621–624.","url":""}]},{"id":"s9-416","number":416,"surah":9,"verses":[72],"verseLabel":"التوبة: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿ورضوان من الله أكبر﴾ مع عظمة الجنة؟","answer":"رضا الله سبب كل نعيم وغاية أعلى من نعيم الجنة نفسه؛ فمهما عظمت المساكن والأنهار كان رضوان المنعم أكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص623–626.","url":""}]},{"id":"s9-417","number":417,"surah":9,"verses":[72],"verseLabel":"التوبة: 72","question":"لماذا نكّر ﴿رضوان﴾؟","answer":"نُكّر ﴿رضوان﴾ للتعظيم؛ أي رضوان عظيم من الله لا تحيط العبارة بقدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص625–627.","url":""}]},{"id":"s9-418","number":418,"surah":9,"verses":[72],"verseLabel":"التوبة: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك هو الفوز العظيم﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يقوي الحكم ويفيد القصر: هذا الجزاء الجامع للنعيم والرضوان هو الفوز العظيم حقًا، لا متاع الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص627–630.","url":""}]},{"id":"s9-419","number":419,"surah":9,"verses":[72],"verseLabel":"التوبة: 72","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران: ﴿ورضوان من الله﴾، وقوله تعالى في التوبة: ﴿ورضوان من الله أكبر﴾؟","answer":"في آل عمران ذُكر الرضوان ضمن تعداد ما هو خير من شهوات الدنيا، فاكتفي بإثباته؛ وفي التوبة سبق تفصيل الجنان والمساكن، فجيء بـ﴿أكبر﴾ للتصريح بأن رضوان الله أعظم من ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص638–639، تحت آل عمران 15.","url":""}]},{"id":"s9-420","number":420,"surah":9,"verses":[89,100,111],"verseLabel":"التوبة: 72؛ التوبة: 89، 100، 111","question":"ما سرّ اختلاف التعبير في سورة التوبة بين: ﴿ذلك هو الفوز العظيم﴾، و﴿ذلك الفوز العظيم﴾، و﴿وذلك هو الفوز العظيم﴾؟","answer":"تختلف أدوات الربط بحسب اتصال الجملة بما قبلها ودرجة التوكيد: في الآية 89 كفت الإشارة لقرب تفصيل الجنة، وفي 72 زيد ﴿هو﴾ لتوكيد أن الرضوان هو الفوز، وفي 111 اجتمعت الواو والإشارة و﴿هو﴾ لشدة اتصال الاستبشار بالبيع وما يتضمنه من الرضوان والخلود.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص137، https://islamweb.net/ar/library/content/224/10/تفسير-سورة-التوبة.","url":""}]},{"id":"s9-421","number":421,"surah":9,"verses":[73],"verseLabel":"التوبة: 73","question":"لماذا جمع النبي ﷺ في أمر واحد بين جهاد الكفار والمنافقين؟","answer":"جمعهما لأن الفريقين يعادون الدعوة، لكن جهاد الكفار يكون بالسلاح والحجة، وجهاد المنافقين بإقامة الحجة وكشف النفاق وإجراء الأحكام والغلظة المناسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص631–635.","url":""}]},{"id":"s9-422","number":422,"surah":9,"verses":[73],"verseLabel":"التوبة: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿واغلظ عليهم﴾ بعد الأمر بالجهاد؟","answer":"الغلظة تمنع أن يحمل المنافقون لين النبي ﷺ على الضعف أو يسترسلوا في الأذى؛ وهي من مقتضيات الجهاد بحسب حال كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص634–637.","url":""}]},{"id":"s9-423","number":423,"surah":9,"verses":[73],"verseLabel":"التوبة: 73","question":"لماذا كانت خاتمة الآية: ﴿ومأواهم جهنم وبئس المصير﴾؟","answer":"بعد الأمر بجهادهم وغلظتهم بينت الخاتمة مآلهم الذي لا يقيهم منه نفاقهم: جهنم مأواهم، وهي أسوأ مرجع ومصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص637–645.","url":""}]},{"id":"s9-424","number":424,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون بالله ما قالوا ولقد قالوا كلمة الكفر﴾؟","answer":"قابل حلفهم المؤكد بالنفي بتوكيدين: اللام و﴿قد﴾ في ﴿ولقد قالوا﴾؛ ففضح كذب اليمين وأثبت قولهم ثبوتًا قاطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص646–650.","url":""}]},{"id":"s9-425","number":425,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"لماذا أبهم القول فقال: ﴿كلمة الكفر﴾ ولم ينقل عبارتهم؟","answer":"أبهمت العبارة تهويلًا لقبحها وصونًا للسان عن حكايتها، ولأن العبرة بوصفها الشرعي الجامع: كلمة كفر، لا بلفظ حادثة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص649–652.","url":""}]},{"id":"s9-426","number":426,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وكفروا بعد إسلامهم﴾ لا «بعد إيمانهم»؟","answer":"﴿إسلامهم﴾ يدل على الانقياد الظاهر الذي أعلنوه، ولا يشهد لهم بإيمان قلبي؛ ثم أظهرت كلمة الكفر حقيقة باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص651–654.","url":""}]},{"id":"s9-427","number":427,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وهموا بما لم ينالوا﴾ ولم يصرح بما هموا به؟","answer":"أبهم ما هموا به ليدخل فيه ما روي من صور المكر، ولتهويل الجريمة مع بيان فشلها؛ فالمهم أنهم قصدوا أمرًا عظيمًا ولم يبلغوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص653–656.","url":""}]},{"id":"s9-428","number":428,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"ما المفارقة في قوله: ﴿وما نقموا إلا أن أغناهم الله ورسوله من فضله﴾؟","answer":"المفارقة أنهم لم يجدوا ما ينقمونه إلا إحسان الله إليهم بالغنى بعد الفقر؛ فصيغ المدح في صورة الذم تهكمًا بهم وإظهارًا لجحودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص655–659.","url":""}]},{"id":"s9-429","number":429,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"لماذا نُسب الإغناء إلى الله ورسوله ثم أُفرد الفضل في ﴿من فضله﴾؟","answer":"الإغناء وقع بتقدير الله وعلى يد رسوله ﷺ في القسمة، أما الفضل فمن الله وحده؛ لذلك عاد الضمير مفردًا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص658–661.","url":""}]},{"id":"s9-430","number":430,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"لماذا فُتح باب التوبة بعد كل هذه الجرائم: ﴿فإن يتوبوا يك خيرًا لهم﴾؟","answer":"فتح باب التوبة بيان لسعة الرحمة وإقامة للحجة؛ فمع عظم جرائمهم يكون رجوعهم خيرًا لهم من الإصرار الذي يجر عذاب الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص660–663.","url":""}]},{"id":"s9-431","number":431,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يتولوا يعذبهم الله عذابًا أليمًا في الدنيا والآخرة﴾؟","answer":"قابل الشرطان طريقين واضحين: التوبة خير لهم، والتولي يفضي إلى عذاب مؤلم في الدنيا والآخرة؛ فاستوعب المآل العاجل والآجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص663–666.","url":""}]},{"id":"s9-432","number":432,"surah":9,"verses":[74],"verseLabel":"التوبة: 74","question":"لماذا ختم بنفي الولي والنصير في الأرض؟","answer":"نفي الولي والنصير يقطع طمعهم في حماية تنفعهم من عذاب الله؛ فلا قريب يتولى أمرهم ولا معين يدفع عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص666–669.","url":""}]},{"id":"s9-433","number":433,"surah":9,"verses":[75],"verseLabel":"التوبة: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من عاهد الله﴾، فنسب العهد إلى الله مباشرة؟","answer":"العهد مع الله يغلظ مسؤولية الوعد؛ فهم لم يعدوا الناس فقط، بل التزموا لله إن رزقهم أن يتصدقوا ويصلحوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص670–673.","url":""}]},{"id":"s9-434","number":434,"surah":9,"verses":[75],"verseLabel":"التوبة: 75","question":"لماذا أكدوا وعدهم باللام والنون: ﴿لنصدقن ولنكونن من الصالحين﴾؟","answer":"اللام ونون التوكيد الثقيلة في الفعلين تشددان الوعد وتكشفان عظم إخلافه حين جاءهم الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص672–675.","url":""}]},{"id":"s9-435","number":435,"surah":9,"verses":[75],"verseLabel":"التوبة: 75","question":"لماذا جمعوا بين الصدقة والصلاح؟","answer":"الصدقة عمل مالي مخصوص، وكونهم من الصالحين وصف أعم يشمل الوفاء والطاعة؛ فوعدوا ببذل المال وإصلاح الحال كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص674–676.","url":""}]},{"id":"s9-436","number":436,"surah":9,"verses":[76],"verseLabel":"التوبة: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما آتاهم من فضله بخلوا به﴾؟","answer":"الفاء تفيد التعقيب: ما إن تحقق الإيتاء حتى قابلوه بالبخل، و﴿من فضله﴾ تذكر بأن المال تفضل من الله لا ملك مستقل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص676–679.","url":""}]},{"id":"s9-437","number":437,"surah":9,"verses":[76],"verseLabel":"التوبة: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿وتولوا وهم معرضون﴾، فجمع بين التولي والإعراض؟","answer":"التولي انصراف بالفعل عن الوفاء والطاعة، والإعراض حال القلب الراسخة؛ فجمع بين حركة الظاهر وصدود الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص678–681.","url":""}]},{"id":"s9-438","number":438,"surah":9,"verses":[76],"verseLabel":"التوبة: 76","question":"لماذا جاءت ﴿وهم معرضون﴾ جملة اسمية؟","answer":"الجملة الاسمية تثبت الإعراض صفة مستقرة فيهم حال توليهم، لا فعلًا طارئًا وقع مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص680–682.","url":""}]},{"id":"s9-439","number":439,"surah":9,"verses":[77],"verseLabel":"التوبة: 77","question":"ما وجه قوله تعالى: ﴿فأعقبهم نفاقًا في قلوبهم﴾ مع وصفهم قبل ذلك بالنفاق؟","answer":"المعنى أن إخلاف العهد والكذب أورثاهم نفاقًا ثابتًا متزايدًا لازم قلوبهم إلى الموت أو لقاء الله؛ فالجزاء زيادة النفاق ورسوخه، لا ابتداء كل نفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص678–681.","url":""}]},{"id":"s9-440","number":440,"surah":9,"verses":[77],"verseLabel":"التوبة: 77","question":"لماذا أسند إعقاب النفاق إلى الله أو إلى البخل بحسب توجيه الضمير؟","answer":"على عود الضمير إلى الله فالإعقاب جزاء إلهي عادل على البخل والإخلاف، وعلى عوده إلى البخل فالمعنى أن فعلهم صار سببًا ملازمًا للنفاق؛ والنتيجة واحدة في ترتيب الجزاء على الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص679–682.","url":""}]},{"id":"s9-441","number":441,"surah":9,"verses":[77],"verseLabel":"التوبة: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم يلقونه﴾ بدل «إلى موتهم»؟","answer":"﴿إلى يوم يلقونه﴾ يستحضر الوقوف بين يدي الله وما بعد الموت من حساب، فهو أبلغ في الوعيد من ذكر الموت وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص681–684.","url":""}]},{"id":"s9-442","number":442,"surah":9,"verses":[77],"verseLabel":"التوبة: 77","question":"لماذا علل النفاق بإخلاف الوعد والكذب معًا؟","answer":"إخلاف الوعد فساد في العمل، والكذب فساد في القول والنية؛ فاجتماعهما كشف نقضهم للعهد من جهتين وأورثهم النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص683–685.","url":""}]},{"id":"s9-443","number":443,"surah":9,"verses":[78],"verseLabel":"التوبة: 78","question":"لماذا سأل: ﴿ألم يعلموا أن الله يعلم سرهم ونجواهم﴾؟","answer":"الاستفهام للتوبيخ والتقرير؛ فلو استحضروا إحاطة علم الله لما أخفوا إخلافهم وتناجوا بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص686–688.","url":""}]},{"id":"s9-444","number":444,"surah":9,"verses":[78],"verseLabel":"التوبة: 78","question":"ما الفرق بين ﴿سرهم﴾ و﴿نجواهم﴾؟","answer":"السر ما يضمره الإنسان أو يخفيه في نفسه، والنجوى حديث خفي بين اثنين فأكثر؛ فجمع علمه بالباطن الفردي والخفي المتبادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص688–690.","url":""}]},{"id":"s9-445","number":445,"surah":9,"verses":[78],"verseLabel":"التوبة: 78","question":"لماذا ختم بـ﴿وأن الله علام الغيوب﴾ بصيغة المبالغة؟","answer":"﴿علّام﴾ صيغة مبالغة تدل على سعة العلم وإحاطته بكل غائب وخفي، فلا يخرج عنه سر ولا نجوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص690–692.","url":""}]},{"id":"s9-446","number":446,"surah":9,"verses":[79],"verseLabel":"التوبة: 79","question":"لماذا وصف المنافقين بأنهم ﴿يلمزون المطوعين﴾؟","answer":"اللمز طعن وعيب؛ فهم يعيبون المتطوعين بالصدقة رياءً إن أكثروا، ويسخرون من المقلين إن بذلوا طاقتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص693–695.","url":""}]},{"id":"s9-447","number":447,"surah":9,"verses":[79],"verseLabel":"التوبة: 79","question":"لماذا جمع بين السخرية من كثير الصدقة وقليلها؟","answer":"جمع الفريقين ليكشف أن غرض المنافقين ليس تقويم الصدقة؛ فكثيرها عندهم رياء وقليلها سخرية، فلا يسلم عندهم صاحب خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص695–698.","url":""}]},{"id":"s9-448","number":448,"surah":9,"verses":[79],"verseLabel":"التوبة: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين لا يجدون إلا جهدهم﴾؟","answer":"القصر بـ﴿لا يجدون إلا جهدهم﴾ يبرز أنهم بذلوا غاية ما يملكون مع قلته، فيعظم إخلاصهم وتشتد بشاعة السخرية منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص697–699.","url":""}]},{"id":"s9-449","number":449,"surah":9,"verses":[79],"verseLabel":"التوبة: 79","question":"لماذا جاء الجزاء بلفظ فعلهم: ﴿سخر الله منهم﴾؟","answer":"جاء الجزاء من جنس العمل على سبيل المشاكلة: لما سخروا من المؤمنين جازاهم الله بالإهانة وكشف مساوئهم، لا على معنى السخرية البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص699–701.","url":""}]},{"id":"s9-450","number":450,"surah":9,"verses":[79],"verseLabel":"التوبة: 79","question":"لماذا ختم بـ﴿ولهم عذاب أليم﴾؟","answer":"العذاب الأليم جزاء يناسب أذاهم للمؤمنين وسخريتهم من الطاعة، والجملة الاسمية تثبت استحقاقه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص700–701.","url":""}]},{"id":"s9-451","number":451,"surah":9,"verses":[80],"verseLabel":"التوبة: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿استغفر لهم أو لا تستغفر لهم﴾ بصيغة التسوية؟","answer":"الأمر للتسوية في انتفاء النتيجة: استغفارك لهم وعدمه سواء ما داموا مصرين على الكفر؛ وليس المقصود طلب أحد الفعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص702–705.","url":""}]},{"id":"s9-452","number":452,"surah":9,"verses":[80],"verseLabel":"التوبة: 80","question":"لماذا ذُكر العدد ﴿سبعين مرة﴾؟","answer":"السبعون تجري في أساليب العرب مجرى التكثير والمبالغة، والمعنى أن كثرة الاستغفار لا تنفعهم مع بقاء سبب المنع، لا أن الزيادة تضمن المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص704–708.","url":""}]},{"id":"s9-453","number":453,"surah":9,"verses":[80],"verseLabel":"التوبة: 80","question":"لماذا علل عدم المغفرة بكفرهم بالله ورسوله؟","answer":"بينت العلة أن المانع ليس قلة الاستغفار، بل كفرهم بالله ورسوله؛ والمغفرة لا تنال مع الإصرار على أصل الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص707–711.","url":""}]},{"id":"s9-454","number":454,"surah":9,"verses":[80],"verseLabel":"التوبة: 80","question":"لماذا ختم بـ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"الخاتمة تعلل عدم المغفرة بأنهم خرجوا عن الطاعة ورسخ الفسق فيهم، فلا يوفقهم الله للهداية ما داموا مختارين لهذا الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص711–718.","url":""}]},{"id":"s9-455","number":455,"surah":9,"verses":[80],"verseLabel":"التوبة: 80","question":"ما سرّ اختلاف التعبير بين قوله تعالى في التوبة: ﴿استغفر لهم أو لا تستغفر لهم إن تستغفر لهم سبعين مرة فلن يغفر الله لهم﴾، وقوله تعالى في المنافقون: ﴿سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم﴾؟","answer":"آية التوبة خاطبت النبي ﷺ بصيغة التسوية وذكرت السبعين على طريق التكثير، فتوهم منها إمكان المغفرة بالزيادة؛ فجاءت آية المنافقون بصيغة الخبر الصريح ﴿سواء عليهم﴾ و﴿لن يغفر الله لهم﴾ لتحسم هذا الوهم ما داموا على النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص715–716، تحت التوبة 67؛ وج62، ص26–27، تحت المنافقون 6.","url":""}]},{"id":"s9-456","number":456,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"لماذا سُمّي المتخلفون ﴿المخلفون﴾ بالبناء للمجهول؟","answer":"﴿المخلّفون﴾ يشعر بأنهم تُركوا وراء الخارجين وحرموا شرف صحبتهم، مع أنهم اختاروا التخلف؛ ففي الصيغة ذم وإبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص719–722.","url":""}]},{"id":"s9-457","number":457,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿بمقعدهم خلاف رسول الله﴾؟","answer":"المقعد مصدر ميمي يصور ملازمتهم مكان القعود، و﴿خلاف رسول الله﴾ أي خلفه ومخالفين له؛ فجمع التخلف المكاني والمعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص722–725.","url":""}]},{"id":"s9-458","number":458,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿كرهوا أن يجاهدوا بأموالهم وأنفسهم﴾؟","answer":"المصدر المؤول يبين متعلق كراهيتهم: نفس الجهاد بالمال والنفس؛ وهو يكشف أن التخلف لم يكن عذرًا بل نفورًا من التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص724–727.","url":""}]},{"id":"s9-459","number":459,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"ما سرّ تقديم الأموال على الأنفس حتى في وصف كراهتهم؟","answer":"قُدمت الأموال لأن الجهاد بها مقدمة لإعداد القتال، ولشدة تعلق المنافقين بالمال؛ فبخلهم به ظاهر قبل بخلهم بالنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص726–729.","url":""}]},{"id":"s9-460","number":460,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"ما دلالة قولهم: ﴿لا تنفروا في الحر﴾؟","answer":"قالوها تثبيطًا لغيرهم واعتذارًا بحر تبوك؛ فجمعوا تخلفهم الشخصي ومحاولة صرف المؤمنين عن النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص728–731.","url":""}]},{"id":"s9-461","number":461,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"لماذا جاء الرد: ﴿قل نار جهنم أشد حرًا﴾؟","answer":"رد عليهم من جنس عذرهم: إن فروا من حر يسير مؤقت فقد عرضوا أنفسهم لحر جهنم الأشد، فالموازنة تبطل حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص731–735.","url":""}]},{"id":"s9-462","number":462,"surah":9,"verses":[81],"verseLabel":"التوبة: 81","question":"لماذا ختم بـ﴿لو كانوا يفقهون﴾ لا «يعلمون»؟","answer":"الفقه فهم ينفذ إلى العواقب، لا مجرد معرفة أن النار أشد حرًا؛ فلو فقهوا لآثروا مشقة الساعة على عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص734–738.","url":""}]},{"id":"s9-463","number":463,"surah":9,"verses":[82],"verseLabel":"التوبة: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿فليضحكوا قليلًا وليبكوا كثيرًا﴾ بصيغة الأمر؟","answer":"الأمران للتهديد والإخبار بالمآل، لا لطلب الضحك والبكاء؛ أي ضحكهم في الدنيا قليل وسيتبعه بكاء كثير في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص739–742.","url":""}]},{"id":"s9-464","number":464,"surah":9,"verses":[82],"verseLabel":"التوبة: 82","question":"لماذا قابل القليل بالكثير والضحك بالبكاء؟","answer":"قابل الضحك بالبكاء والقليل بالكثير لإظهار التفاوت بين متاعهم العاجل القصير وحسرتهم وعذابهم الطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص741–744.","url":""}]},{"id":"s9-465","number":465,"surah":9,"verses":[82],"verseLabel":"التوبة: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿جزاء بما كانوا يكسبون﴾، فاختار الكسب؟","answer":"الكسب يدل على عمل تعمدوه واكتسبوه باختيارهم؛ فالعقوبة جزاء ما داوموا على تحصيله من النفاق والتثبيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص744–748.","url":""}]},{"id":"s9-466","number":466,"surah":9,"verses":[83],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن رجعك الله إلى طائفة منهم﴾، دون أن يقال: «إذا رجعت»؟","answer":"إسناد الإرجاع إلى الله يذكر بأن عودة النبي ﷺ إليهم بتقديره، ويتضمن أن الحكم سيقع إذا رده الله سالمًا، لا بمجرد رجوع عادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص749–752.","url":""}]},{"id":"s9-467","number":467,"surah":9,"verses":[83],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى طائفة منهم﴾ لا «إليهم»؟","answer":"قال ﴿طائفة منهم﴾ لأن بعض المتخلفين قد يهلك أو يغيب، ولأن الحكم متعلق بمن بقي ممن استحق هذا التأديب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص751–754.","url":""}]},{"id":"s9-468","number":468,"surah":9,"verses":[83],"verseLabel":"التوبة: 83","question":"لماذا نهى بقوله: ﴿لن تخرجوا معي أبدًا ولن تقاتلوا معي عدوًا﴾؟","answer":"المنع عقوبة تربوية توافق جرمهم: لما تركوا الخروج أول مرة حرموا شرف الخروج والقتال بعد ذلك، وأكد بـ﴿لن﴾ و﴿أبدًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص754–758.","url":""}]},{"id":"s9-469","number":469,"surah":9,"verses":[83],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿رضيتم بالقعود أول مرة﴾؟","answer":"﴿رضيتم﴾ يثبت أن القعود كان اختيارًا استحسنوه لا اضطرارًا، و﴿أول مرة﴾ تجعل موقف تبوك أصلًا يترتب عليه حرمانهم اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص757–760.","url":""}]},{"id":"s9-470","number":470,"surah":9,"verses":[83],"verseLabel":"التوبة: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فاقعدوا مع الخالفين﴾؟","answer":"الأمر للإهانة والتثبيت على الجزاء: الزموا القعود مع من شأنهم التخلف، بعد أن رضيتم لأنفسكم به حين دعاكم الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص760–766.","url":""}]},{"id":"s9-471","number":471,"surah":9,"verses":[84],"verseLabel":"التوبة: 84","question":"لماذا نُهي النبي ﷺ عن الصلاة على أحد منهم مات أبدًا؟","answer":"النهي الدائم يقطع ما في الصلاة عليه من تكريم ودعاء واستغفار؛ لأن موته على الكفر يمنع المغفرة ويكشف حقيقة نفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص767–770.","url":""}]},{"id":"s9-472","number":472,"surah":9,"verses":[84],"verseLabel":"التوبة: 84","question":"لماذا جمع بين ﴿ولا تصل على أحد﴾ و﴿ولا تقم على قبره﴾؟","answer":"الصلاة دعاء للميت، والقيام على القبر يشمل شهود دفنه والدعاء له؛ فجمع النهي عن وجهي التكريم بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص769–772.","url":""}]},{"id":"s9-473","number":473,"surah":9,"verses":[84],"verseLabel":"التوبة: 84","question":"لماذا علل النهي بأنهم كفروا وماتوا وهم فاسقون؟","answer":"الكفر يبين فساد الاعتقاد، والموت على الفسق يبين استمرار الخروج عن الطاعة إلى النهاية؛ فالعبرة بالخاتمة من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص772–775.","url":""}]},{"id":"s9-474","number":474,"surah":9,"verses":[84],"verseLabel":"التوبة: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿ماتوا وهم فاسقون﴾، دون أن يقال: «منافقون»؟","answer":"الفسق أعم من النفاق ويبرز خروجهم المستمر عن طاعة الله حتى الموت؛ وكل نفاق فسق، وليس كل فسق نفاقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص775–777.","url":""}]},{"id":"s9-475","number":475,"surah":9,"verses":[85],"verseLabel":"التوبة: 85","question":"لماذا تكرر النهي: ﴿ولا تعجبك أموالهم وأولادهم﴾ من الآية 55؟","answer":"تكرر النهي لأن السياق انتقل إلى طائفة أخرى من المنافقين وتجدد ما قد يثير الإعجاب، فاستؤنف التحذير مع بيان العلة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص778–781.","url":""}]},{"id":"s9-476","number":476,"surah":9,"verses":[85],"verseLabel":"التوبة: 85","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿أن يعذبهم بها في الدنيا﴾، وقال سابقًا: ﴿في الحياة الدنيا﴾؟","answer":"ذُكرت ﴿الحياة الدنيا﴾ أولًا بتمام الموصوف والصفة، ثم حذف الموصوف هنا اكتفاء بسبق ذكره؛ والدنيا هي الحياة القريبة المقابلة للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص781–785.","url":""}]},{"id":"s9-477","number":477,"surah":9,"verses":[85],"verseLabel":"التوبة: 85","question":"لماذا أعيدت خاتمة ﴿وتزهق أنفسهم وهم كافرون﴾؟","answer":"أعيدت لتأكيد وحدة عاقبة هذه الطائفة: تعذبهم النعم في الدنيا ثم تخرج أرواحهم وهم مصرون على الكفر، فيتصل العذابان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص785–792.","url":""}]},{"id":"s9-478","number":478,"surah":9,"verses":[86],"verseLabel":"التوبة: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا أنزلت سورة أن آمنوا بالله وجاهدوا مع رسوله﴾؟","answer":"﴿أن آمنوا﴾ تفسر مضمون السورة المنزلة: الأمر بتحقيق الإيمان والجهاد مع الرسول ﷺ؛ فظهر التناقض بين دعواهم والاستئذان في القعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص793–796.","url":""}]},{"id":"s9-479","number":479,"surah":9,"verses":[86],"verseLabel":"التوبة: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿استأذنك أولو الطول منهم﴾، وخص أهل القدرة؟","answer":"﴿أولو الطول﴾ أصحاب السعة والقدرة، وخصوا لأن استئذان العاجز قد يعذر، أما استئذان القادر فيكشف النفاق وشدة التعلق بالدعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص795–798.","url":""}]},{"id":"s9-480","number":480,"surah":9,"verses":[86],"verseLabel":"التوبة: 86","question":"ما دلالة قولهم: ﴿ذرنا نكن مع القاعدين﴾؟","answer":"﴿ذرنا﴾ طلب ترك يحمل معنى التعلل والإصرار، و﴿مع القاعدين﴾ يكشف رضاهم بالانضمام إلى أهل الأعذار ومن لا ينهض للجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص797–802.","url":""}]},{"id":"s9-481","number":481,"surah":9,"verses":[87],"verseLabel":"التوبة: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿رضوا بأن يكونوا مع الخوالف﴾، فجعل القعود موضع رضا؟","answer":"جعل القعود موضع رضا لبيان أنهم لم يقعوا فيه كارهين أو معذورين، بل اختاروا منزلة الخوالف واستحبوها على صحبة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص10–13.","url":""}]},{"id":"s9-482","number":482,"surah":9,"verses":[87],"verseLabel":"التوبة: 87","question":"لماذا اختيرت ﴿الخوالف﴾ لا «القاعدين»؟","answer":"﴿الخوالف﴾ يغلب في النساء أو من شأنه البقاء خلف الخارجين، فاختيارها أشد إزراء بالرجال القادرين الذين رضوا لأنفسهم هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص12–15.","url":""}]},{"id":"s9-483","number":483,"surah":9,"verses":[87],"verseLabel":"التوبة: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿وطبع على قلوبهم﴾ بالبناء للمجهول؟","answer":"بني للمجهول لأن المقصود إبراز وقوع الطبع ونتيجته، والفاعل معلوم وهو الله جزاءً على اختيارهم الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص14–17.","url":""}]},{"id":"s9-484","number":484,"surah":9,"verses":[87],"verseLabel":"التوبة: 87","question":"ما الصورة في ﴿طبع على قلوبهم﴾؟","answer":"شُبهت قلوبهم بشيء ختم عليه فلا يدخله نور ولا يخرج ما فيه؛ فهي استعارة تصور انغلاقها عن فهم الحق وقبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص16–19.","url":""}]},{"id":"s9-485","number":485,"surah":9,"verses":[87],"verseLabel":"التوبة: 87","question":"لماذا كانت النتيجة: ﴿فهم لا يفقهون﴾ لا «لا يعلمون»؟","answer":"الفقه فهم دقيق يثمر اعتبارًا وعملًا؛ وقد حجب الطبع قلوبهم عن هذا الفهم، وإن أدركوا ظواهر الأقوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص19–21.","url":""}]},{"id":"s9-486","number":486,"surah":9,"verses":[88],"verseLabel":"التوبة: 88","question":"لماذا استدرك بقوله: ﴿لكن الرسول والذين آمنوا معه﴾ بعد وصف المتخلفين؟","answer":"﴿لكن﴾ تستدرك فتدفع توهم أن التخلف شمل الجميع، وتبرز في مقابله موقف الرسول ﷺ والمؤمنين الذين جاهدوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص22–25.","url":""}]},{"id":"s9-487","number":487,"surah":9,"verses":[88],"verseLabel":"التوبة: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿الرسول﴾ بالوصف ولم يذكر اسمه؟","answer":"وصف ﴿الرسول﴾ يستحضر موجب اتباعه ونصره؛ فالجهاد معه مقتضى رسالته، والتخلف عنه مخالفة لوظيفته في الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص24–27.","url":""}]},{"id":"s9-488","number":488,"surah":9,"verses":[88],"verseLabel":"التوبة: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿جاهدوا بأموالهم وأنفسهم﴾، وأعاد الوصف المألوف؟","answer":"إعادة الأموال والأنفس تقابل كراهة المنافقين لهما، وتبين أن المؤمنين بذلوا أعز ما يملكون في الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص26–29.","url":""}]},{"id":"s9-489","number":489,"surah":9,"verses":[88],"verseLabel":"التوبة: 88","question":"لماذا أبهم الخيرات في ﴿وأولئك لهم الخيرات﴾؟","answer":"جمع ﴿الخيرات﴾ وعرفها لتشمل كل خير في الدنيا والآخرة مما لا يحصى، من النصر والذكر الحسن والثواب والجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص28–31.","url":""}]},{"id":"s9-490","number":490,"surah":9,"verses":[88],"verseLabel":"التوبة: 88","question":"لماذا كرر اسم الإشارة: ﴿وأولئك لهم الخيرات وأولئك هم المفلحون﴾؟","answer":"كرر الإشارة ليجعل لكل بشارة استقلالًا: لهم جميع الخيرات، وهم المفلحون؛ وضمير الفصل يؤكد اختصاصهم بالفلاح الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص30–33.","url":""}]},{"id":"s9-491","number":491,"surah":9,"verses":[89],"verseLabel":"التوبة: 89","question":"لماذا انتقل من ﴿الخيرات﴾ إلى تفصيل الجنات؟","answer":"فصلت الجنات بعد إجمال ﴿الخيرات﴾ لبيان أعظم خيرات الآخرة وتشويق النفس إليها بعد الوعد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص34–36.","url":""}]},{"id":"s9-492","number":492,"surah":9,"verses":[89],"verseLabel":"التوبة: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿تجري من تحتها الأنهار﴾ لا «فيها أنهار»؟","answer":"التعبير بالجريان من تحتها يصور الأنهار دائمة الحركة قريبة من قصورها وأشجارها وتحت تصرف أهلها، وهو أبلغ من مجرد وجودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص35–38.","url":""}]},{"id":"s9-493","number":493,"surah":9,"verses":[89],"verseLabel":"التوبة: 89","question":"لماذا جمع بين ﴿خالدين فيها﴾ و﴿ذلك الفوز العظيم﴾؟","answer":"﴿خالدين فيها﴾ ينفي انقطاع النعيم، و﴿ذلك الفوز العظيم﴾ يحكم بأن نيل المحبوب الدائم والنجاة من المكروه هو الفوز الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص38–41.","url":""}]},{"id":"s9-494","number":494,"surah":9,"verses":[90],"verseLabel":"التوبة: 90","question":"لماذا فرّق بين ﴿المعذرون﴾ و﴿الذين كذبوا الله ورسوله﴾؟","answer":"﴿المعذرون﴾ جاؤوا يطلبون الإذن ويظهرون عذرًا، وقد يكون فيهم صادق أو مقصر؛ أما الآخرون فقعدوا بلا اعتذار وكذبوا الله ورسوله، فكان جرمهم أصرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص42–46.","url":""}]},{"id":"s9-495","number":495,"surah":9,"verses":[90],"verseLabel":"التوبة: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاء المعذرون﴾، بينما قال عن الآخرين: ﴿وقعد الذين كذبوا﴾؟","answer":"المعذرون تحملوا المجيء لعرض أعذارهم، أما المكذبون فقعدوا من غير اكتراث ولا محاولة اعتذار؛ فاختلاف الفعلين يصور تفاوت الحال والجرأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص45–49.","url":""}]},{"id":"s9-496","number":496,"surah":9,"verses":[90],"verseLabel":"التوبة: 90","question":"ما وجه توجيه التكذيب إلى الله ورسوله في قوله تعالى: ﴿كذبوا الله ورسوله﴾؟","answer":"معنى ﴿كذبوا الله ورسوله﴾ أنهم كذبوا في دعواهم وأيمانهم فيما يعاملون به الله ورسوله، أو كذبوا ما أخبرا به؛ فالتكذيب متوجه إلى الخبر والعهد، لا إلى ذات المخاطَب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص48–51.","url":""}]},{"id":"s9-497","number":497,"surah":9,"verses":[90],"verseLabel":"التوبة: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿سيصيب الذين كفروا منهم عذاب أليم﴾، فأدخل ﴿منهم﴾؟","answer":"﴿منهم﴾ للتبعيض؛ لأن الأعراب المذكورين ليسوا جميعًا كافرين، بل فيهم معذرون أو مؤمنون، فالوعيد يخص من ثبت كفره منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص51–56.","url":""}]},{"id":"s9-498","number":498,"surah":9,"verses":[91],"verseLabel":"التوبة: 91","question":"لماذا جمع الضعفاء والمرضى ومن لا يجدون ما ينفقون؟","answer":"جمعت الآية أصحاب الأعذار التي تمنع الجهاد: ضعف البدن، والمرض، وفقد النفقة؛ فاستوعبت العجز الخِلقي والعارض والمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص57–61.","url":""}]},{"id":"s9-499","number":499,"surah":9,"verses":[91],"verseLabel":"التوبة: 91","question":"لماذا اشترط لرفع الحرج: ﴿إذا نصحوا لله ورسوله﴾؟","answer":"رفع الحرج مشروط ببقاء صدقهم وإخلاصهم: ينصحون لله ورسوله ولا يثبطون ولا يخونون، ويؤدون ما قدروا عليه من وجوه الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص60–64.","url":""}]},{"id":"s9-500","number":500,"surah":9,"verses":[91],"verseLabel":"التوبة: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿ما على المحسنين من سبيل﴾، فنفى كل سبيل؟","answer":"﴿من﴾ الزائدة في سياق النفي تفيد الاستغراق: لا طريق إلى لوم المحسنين أو عقابهم من أي وجه ما دام العذر صحيحًا والنصح قائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص63–67.","url":""}]},{"id":"s9-501","number":501,"surah":9,"verses":[91],"verseLabel":"التوبة: 91","question":"لماذا وصف أصحاب الأعذار بـ﴿المحسنين﴾؟","answer":"وصفوا بالمحسنين لأنهم مع عجزهم صدقوا النية ونصحوا وبذلوا ما استطاعوا؛ فالإحسان بحسب القدرة لا بمجرد المشاركة البدنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص66–69.","url":""}]},{"id":"s9-502","number":502,"surah":9,"verses":[91],"verseLabel":"التوبة: 91","question":"لماذا ختم بـ﴿والله غفور رحيم﴾؟","answer":"﴿غفور﴾ يستر ما يعجز عنه أصحاب الأعذار، و﴿رحيم﴾ لا يكلفهم ما لا يطيقون ويرفع عنهم الحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص69–73.","url":""}]},{"id":"s9-503","number":503,"surah":9,"verses":[92],"verseLabel":"التوبة: 92","question":"لماذا أفرد بالذكر الذين جاؤوا ليُحملوا بعد إدخالهم فيمن لا يجدون ما ينفقون؟","answer":"أفردوا لأن حالهم أبلغ: لم يكتفوا بالرغبة، بل جاؤوا يطلبون ما يحملهم، ثم بكوا حين لم يجدوا؛ فاستحق إخلاصهم تنويهًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص74–77.","url":""}]},{"id":"s9-504","number":504,"surah":9,"verses":[92],"verseLabel":"التوبة: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿قلت لا أجد ما أحملكم عليه﴾، فنسب عدم الوجود إلى النبي ﷺ؟","answer":"نسب عدم الوجود إليه ﷺ لأنه المسؤول عن تجهيز الجيش وصاحب القسمة، فنفى أن يكون عنده مركوب يهيئه لهم، لا أنه منعهم مع القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص76–79.","url":""}]},{"id":"s9-505","number":505,"surah":9,"verses":[92],"verseLabel":"التوبة: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿تولوا وأعينهم تفيض من الدمع﴾؟","answer":"التولي يصور رجوعهم مكرهين، و﴿أعينهم تفيض من الدمع﴾ مبالغة؛ كأن العين نفسها فاضت لكثرة الدموع، فكشف الظاهر صدق حزنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص78–82.","url":""}]},{"id":"s9-506","number":506,"surah":9,"verses":[92],"verseLabel":"التوبة: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿حزنًا ألا يجدوا ما ينفقون﴾، دون أن يقال: حزنًا على عدم الخروج؟","answer":"ذكر فقد النفقة لأنه العائق المباشر عن الخروج، وفيه أنهم كانوا يملكون الرغبة والقوة ولم يحبسهم إلا عدم وسيلة الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص81–84.","url":""}]},{"id":"s9-507","number":507,"surah":9,"verses":[92],"verseLabel":"التوبة: 92","question":"ما المقابلة بين بكاء هؤلاء وضحك المنافقين في الآية 82؟","answer":"هؤلاء بكوا كثيرًا لأنهم حرموا الطاعة مع صدقهم، والمنافقون ضحكوا قليلًا لفرحهم بالتخلف؛ فالمقابلة تميز حزن الإيمان من فرح النفاق وتبين اختلاف العاقبتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص83–87.","url":""}]},{"id":"s9-508","number":508,"surah":9,"verses":[93],"verseLabel":"التوبة: 93","question":"لماذا حصر المؤاخذة بقوله: ﴿إنما السبيل على الذين يستأذنونك وهم أغنياء﴾؟","answer":"﴿إنما﴾ تقصر اللوم والعقوبة على القادرين الذين يستأذنون في القعود، بعد رفع الحرج عن أصحاب الأعذار الصادقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص88–90.","url":""}]},{"id":"s9-509","number":509,"surah":9,"verses":[93],"verseLabel":"التوبة: 93","question":"لماذا وصفهم بالغنى بدل القوة أو الصحة؟","answer":"الغنى يدل على امتلاك النفقة والوسيلة، وهو موضع العذر السابق؛ فإذا كانوا أغنياء انتفى عذر العجز المالي وظهر اختيارهم للقعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص90–92.","url":""}]},{"id":"s9-510","number":510,"surah":9,"verses":[93],"verseLabel":"التوبة: 93","question":"لماذا كرر: ﴿رضوا بأن يكونوا مع الخوالف﴾؟","answer":"كررها لتأكيد أن القعود كان موضع رضا واختيار من طائفة أخرى من القادرين، لا عذرًا عارضًا؛ وفي التكرار زيادة تقبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص92–94.","url":""}]},{"id":"s9-511","number":511,"surah":9,"verses":[93],"verseLabel":"التوبة: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿وطبع الله على قلوبهم﴾ هنا بإظهار اسم الله، وقال في الآية 87: ﴿وطبع على قلوبهم﴾؟","answer":"في الآية 87 سبق البناء للمجهول في ﴿أنزلت﴾ فناسبه ﴿طبع﴾، وهنا تكرر اسم الله في السياق فصرح به: ﴿وطبع الله﴾؛ وفي الحالين الطبع جزاء إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص94–96.","url":""}]},{"id":"s9-512","number":512,"surah":9,"verses":[93],"verseLabel":"التوبة: 93","question":"لماذا ختم بـ﴿فهم لا يعلمون﴾، بينما ختمت الآية 87 بـ﴿فهم لا يفقهون﴾؟","answer":"ختمت الأولى بـ﴿لا يفقهون﴾ مع إسناد الطبع للمجهول، وهنا بـ﴿لا يعلمون﴾ مع إسناده إلى الله؛ والعلم أرفع من الفقه في هذا التوجيه، فناسب الأقوى الأقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص95–96.","url":""}]},{"id":"s9-513","number":513,"surah":9,"verses":[94],"verseLabel":"التوبة: 94","question":"لماذا أخبر أنهم سيعتذرون ﴿إذا رجعتم إليهم﴾ قبل وقوع الاعتذار؟","answer":"الإخبار قبل وقوعه دليل على صدق الوحي وكشف لما أضمروه، ويهيئ المؤمنين لئلا يخدعوا بأعذار مصنوعة عند الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص97–100.","url":""}]},{"id":"s9-514","number":514,"surah":9,"verses":[94],"verseLabel":"التوبة: 94","question":"لماذا جاء الرد: ﴿قل لا تعتذروا لن نؤمن لكم﴾؟","answer":"نُهوا عن الاعتذار لأن الله كشف أخبارهم، و﴿لن نؤمن لكم﴾ أي لن نصدقكم؛ فانتفى أثر كلامهم بعد ظهور كذبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص100–104.","url":""}]},{"id":"s9-515","number":515,"surah":9,"verses":[94],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿قد نبأنا الله من أخباركم﴾؟","answer":"النبأ خبر ذو شأن، و﴿من أخباركم﴾ يفيد أن الله أطلع رسوله ﷺ على القدر الكافي من خفاياهم؛ فلا مجال لسترها بالاعتذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص103–107.","url":""}]},{"id":"s9-516","number":516,"surah":9,"verses":[94],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وسيرى الله عملكم ورسوله﴾، فأعاد باب العمل بعد الأعذار؟","answer":"بعد إبطال الأقوال أحال الحكم إلى العمل المستقبل؛ فصدق التوبة لا تثبته الأعذار، بل ما سيراه الله ورسوله من أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص106–110.","url":""}]},{"id":"s9-517","number":517,"surah":9,"verses":[94],"verseLabel":"التوبة: 94","question":"لماذا وصف الله بـ﴿عالم الغيب والشهادة﴾ في خاتمة الآية؟","answer":"وصفه بـ﴿عالم الغيب والشهادة﴾ لأنه يعلم أعذارهم الباطنة وأعمالهم الظاهرة، فلا تخفى عليه حقيقة التوبة ولا النفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص109–114.","url":""}]},{"id":"s9-518","number":518,"surah":9,"verses":[94],"verseLabel":"التوبة: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فينبئكم بما كنتم تعملون﴾ مع أنهم يعرفون أعمالهم؟","answer":"الإنباء هنا إظهار حقيقة الأعمال والحكم عليها والجزاء بها يوم القيامة، لا مجرد إخبارهم بوقائع يعرفونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص113–120.","url":""}]},{"id":"s9-519","number":519,"surah":9,"verses":[105],"verseLabel":"التوبة: 94؛ التوبة: 105","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الآية 94: ﴿وسيرى الله عملكم ورسوله ثم تردون﴾، وقوله في الآية 105: ﴿فسيرى الله عملكم ورسوله والمؤمنون وستردون﴾؟","answer":"الأولى في المنافقين الذين لا يطلع على ضمائرهم إلا الله ورسوله بإطلاع الله، فاقتصر عليهما وجاء ﴿ثم تردون﴾ وعيدًا؛ والثانية في التائبين المؤمنين وأعمال طاعتهم ظاهرة للمؤمنين، فزيدوا وجاء ﴿وستردون﴾ متصلًا بالوعد.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص137–138، https://islamweb.net/ar/library/content/224/10/تفسير-سورة-التوبة.","url":""}]},{"id":"s9-520","number":520,"surah":9,"verses":[95],"verseLabel":"التوبة: 95","question":"لماذا سيحلفون بالله عند الرجوع: ﴿لتعرضوا عنهم﴾؟","answer":"يحلفون لتكون غاية المؤمنين مجرد ترك اللوم والمؤاخذة، لا التصديق والمحبة؛ فهم يريدون السلامة من تبعات تخلفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص121–125.","url":""}]},{"id":"s9-521","number":521,"surah":9,"verses":[95],"verseLabel":"التوبة: 95","question":"لماذا جاء الأمر: ﴿فأعرضوا عنهم﴾ موافقًا لما طلبوه؟","answer":"أُمروا بالإعراض لا عفوًا ولا رضا، بل إعراض هجر واحتقار؛ فوافق اللفظ مطلوبهم وخالف مرادهم، إذ أرادوا سلامة وقبولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص124–128.","url":""}]},{"id":"s9-522","number":522,"surah":9,"verses":[95],"verseLabel":"التوبة: 95","question":"لماذا علل الإعراض بقوله: ﴿إنهم رجس﴾؟","answer":"الرجس الخبث المعنوي الناشئ من النفاق والكذب؛ فالبعد عنهم صيانة للمؤمنين لا استجابة تكريم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص127–132.","url":""}]},{"id":"s9-523","number":523,"surah":9,"verses":[95],"verseLabel":"التوبة: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿ومأواهم جهنم جزاء بما كانوا يكسبون﴾؟","answer":"جهنم مستقرهم الذي يأوون إليه، و﴿جزاء بما كانوا يكسبون﴾ يقرر أن المصير مقابل لما تعمدوا اكتسابه من الكذب والنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص131–136.","url":""}]},{"id":"s9-524","number":524,"surah":9,"verses":[96],"verseLabel":"التوبة: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿يحلفون لكم لترضوا عنهم﴾ بعد قوله في الآية السابقة ﴿لتعرضوا عنهم﴾؟","answer":"في الأولى غاية الحلف أن يترك المؤمنون عتابهم، ثم ارتفع طمعهم هنا إلى الرضا عنهم؛ فكشف تدرجهم في طلب ستر الجريمة بلا توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص136–139.","url":""}]},{"id":"s9-525","number":525,"surah":9,"verses":[96],"verseLabel":"التوبة: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن ترضوا عنهم فإن الله لا يرضى عن القوم الفاسقين﴾؟","answer":"رضا الناس لا يغير حكم الله؛ فإن رضي المؤمنون ظاهرًا بسبب الحلف، فإن الله لا يرضى عن قوم رسخ فسقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص139–143.","url":""}]},{"id":"s9-526","number":526,"surah":9,"verses":[96],"verseLabel":"التوبة: 96","question":"لماذا لم ينه المؤمنين مباشرة عن الرضا، بل بيّن أن الله لا يرضى؟","answer":"بيّن ميزان الرضا الأعلى ليكون ترك رضاهم ناشئًا من موافقة رضا الله، وهو أبلغ في التربية من نهي مجرد لا يذكر علته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص141–143.","url":""}]},{"id":"s9-527","number":527,"surah":9,"verses":[97],"verseLabel":"التوبة: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿الأعراب أشد كفرًا ونفاقًا﴾، دون أن يقال: «كل الأعراب كفار»؟","answer":"ليس في الآية تعميم الحكم على جميع الأعراب؛ بل بيان أن بيئة البداوة فيمن كفر أو نافق تجعل كفره ونفاقه أشد لبعده عن العلم، وقد استثنت الآيات التالية مؤمنيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص144–147.","url":""}]},{"id":"s9-528","number":528,"surah":9,"verses":[97],"verseLabel":"التوبة: 97","question":"لماذا جمع بين الكفر والنفاق في وصف الأعراب؟","answer":"جمعهما لاستيعاب الفريقين: من أظهر الكفر ومن ستره بالنفاق، أو لأن بعضهم جمع شدة الكفر الباطن وإظهار الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص146–149.","url":""}]},{"id":"s9-529","number":529,"surah":9,"verses":[97],"verseLabel":"التوبة: 97","question":"لماذا علل شدتهم بأنهم ﴿أجدر ألا يعلموا حدود ما أنزل الله﴾؟","answer":"البعد عن مجالس الوحي والعلم يجعلهم أولى بالجهل بحدود الشريعة، وهذا الجهل يزيد غلظ كفرهم ونفاقهم وآثارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص148–151.","url":""}]},{"id":"s9-530","number":530,"surah":9,"verses":[97],"verseLabel":"التوبة: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿حدود ما أنزل الله على رسوله﴾؟","answer":"الحدود هي أحكام الله الفاصلة بين الحلال والحرام والطاعة والمعصية، وإضافتها إلى ما أنزل وربطها بالرسول ﷺ يثبت مصدرها وطريق تبليغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص150–153.","url":""}]},{"id":"s9-531","number":531,"surah":9,"verses":[97],"verseLabel":"التوبة: 97","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بحقيقة كل أعرابي فلا يعمم الحكم على غير أهله، و﴿حكيم﴾ في تفريقه بين الفريقين وترتيب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص152–154.","url":""}]},{"id":"s9-532","number":532,"surah":9,"verses":[98],"verseLabel":"التوبة: 98","question":"ما سرّ التعبير في قوله تعالى عن بعض الأعراب: ﴿يتخذ ما ينفق مغرمًا﴾؟","answer":"يعد النفقة غرامة وخسارة لازمة لا قربة؛ لأنه يدفعها كارهًا بلا إيمان بثوابها، فكشف اللفظ ميزانه المادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص155–158.","url":""}]},{"id":"s9-533","number":533,"surah":9,"verses":[98],"verseLabel":"التوبة: 98","question":"لماذا عبّر بالمضارع ﴿يتخذ﴾ و﴿يتربص﴾؟","answer":"المضارعان يصوران تجدد اتخاذ النفقة مغرمًا واستمرار انتظار المصائب بالمؤمنين؛ فليس ذلك خاطرًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص157–160.","url":""}]},{"id":"s9-534","number":534,"surah":9,"verses":[98],"verseLabel":"التوبة: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتربص بكم الدوائر﴾ بصيغة الجمع؟","answer":"الدوائر جمع دائرة، وهي تقلبات الدهر ومصائبه؛ والجمع يدل على ترقبهم أنواع النكبات متتابعة بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص159–162.","url":""}]},{"id":"s9-535","number":535,"surah":9,"verses":[98],"verseLabel":"التوبة: 98","question":"لماذا جاء الجزاء: ﴿عليهم دائرة السوء﴾ من جنس لفظهم؟","answer":"رد الدعاء عليهم من جنس لفظهم: ما تمنوه للمؤمنين يحيق بهم، و﴿دائرة السوء﴾ تخصهم بالدائرة القبيحة العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص161–164.","url":""}]},{"id":"s9-536","number":536,"surah":9,"verses":[98],"verseLabel":"التوبة: 98","question":"لماذا ختم بـ﴿والله سميع عليم﴾؟","answer":"﴿سميع﴾ لأقوالهم ودعائهم الخفي، و﴿عليم﴾ بما تضمره قلوبهم من تربص وكراهة؛ فلا يخفى نفاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص164–167.","url":""}]},{"id":"s9-537","number":537,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"لماذا استدرك بصورة أخرى من الأعراب: ﴿ومن الأعراب من يؤمن بالله واليوم الآخر﴾؟","answer":"جاءت المقابلة لرفع التعميم: ليس الأعراب سواء، فمنهم مؤمن صادق يجعل نفقته قربة بعد ذكر من يجعلها مغرمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص168–171.","url":""}]},{"id":"s9-538","number":538,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"لماذا تكرر تركيب ﴿يتخذ ما ينفق﴾ في الفريقين مع اختلاف النتيجة؟","answer":"اتحد العمل الظاهر وهو الإنفاق، واختلفت النية: الكافر يراه غرامة، والمؤمن يتخذه قربات؛ فدل التكرار على أن قيمة العمل بنيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص170–174.","url":""}]},{"id":"s9-539","number":539,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿قربات عند الله وصلوات الرسول﴾؟","answer":"النفقة تقربهم إلى الله، ودعاء الرسول ﷺ لهم بالخير والبركة أثر من آثار صدقهم؛ فجمع قبول الله ودعاء رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص173–176.","url":""}]},{"id":"s9-540","number":540,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"لماذا جاءت ﴿قربات﴾ و﴿صلوات﴾ بالجمع؟","answer":"الجمع يدل على تعدد وجوه التقرب بتعدد النفقات والطاعات، وتكرر دعوات الرسول ﷺ وبركاته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص175–178.","url":""}]},{"id":"s9-541","number":541,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"لماذا أكد بقوله: ﴿ألا إنها قربة لهم﴾؟","answer":"﴿ألا﴾ للتنبيه و﴿إن﴾ للتوكيد؛ فردت توهم بطلان نفقتهم لبداوتهم، وثبت أنها قربة محققة لا مجرد ظن منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص177–179.","url":""}]},{"id":"s9-542","number":542,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿سيدخلهم الله في رحمته﴾، فصوّر الرحمة مكانًا يدخلونه؟","answer":"صورت الرحمة فضاء يحيط بهم ويدخلون فيه، للدلالة على شمولها وتمكنهم منها؛ والسين وعد بتحقق ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص179–180.","url":""}]},{"id":"s9-543","number":543,"surah":9,"verses":[99],"verseLabel":"التوبة: 99","question":"لماذا ختم بـ﴿إن الله غفور رحيم﴾؟","answer":"﴿غفور﴾ لما يقع منهم من تقصير، و﴿رحيم﴾ يقبل نفقتهم ويدخلهم في رحمته؛ فناسبت الخاتمة وعد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص180.","url":""}]},{"id":"s9-544","number":544,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"ما سرّ تقديم ﴿السابقون الأولون﴾ قبل المهاجرين والأنصار؟","answer":"﴿السابقون﴾ وصف جامع، ثم بين أنهم الأوائل من المهاجرين والأنصار؛ وتقديم الوصف يشرف السبق نفسه ويجعله أساس المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص181–185.","url":""}]},{"id":"s9-545","number":545,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿من المهاجرين والأنصار﴾، فقدم المهاجرين؟","answer":"قُدم المهاجرون لسبقهم إلى الإيمان وتحملهم مفارقة الديار والأموال، ثم الأنصار الذين آووا ونصروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص184–188.","url":""}]},{"id":"s9-546","number":546,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"لماذا قيد أتباعهم بقوله: ﴿بإحسان﴾؟","answer":"قيد الاتباع بالإحسان حتى لا تكون مجرد الدعوى أو الصحبة كافية؛ بل لا بد من اقتفاء منهج السابقين في صحة الاعتقاد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص187–190.","url":""}]},{"id":"s9-547","number":547,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"رضاه عنهم قبول لأعمالهم وثناء عليهم، ورضاهم عنه فرح بما أعطاهم وتسليم بحكمه؛ فاجتمع رضا الرب والعبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص189–193.","url":""}]},{"id":"s9-548","number":548,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"ما سرّ تقديم رضا الله عنهم على رضاهم عنه؟","answer":"رضا الله هو الأصل والسبب الذي يفيض عليهم النعيم فيرضون، كما أن فضله سابق على طاعتهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص192–195.","url":""}]},{"id":"s9-549","number":549,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"لماذا جمع بين الرضوان وإعداد الجنات؟","answer":"الرضوان نعيم معنوي وسبب القبول، والجنات نعيم حسي دائم؛ فجمع كرامة القرب ومتعة المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص194–198.","url":""}]},{"id":"s9-550","number":550,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿خالدين فيها أبدًا﴾ ثم ﴿ذلك الفوز العظيم﴾؟","answer":"﴿خالدين﴾ ينفي الانقطاع، و﴿أبدًا﴾ يؤكد امتداد الخلود، ثم جعل هذا الجزاء هو الفوز العظيم الذي لا يدانيه فوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص197–203.","url":""}]},{"id":"s9-551","number":551,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"لماذا قدّم في التوبة: ﴿رضي الله عنهم ورضوا عنه﴾ على ذكر الجنات، بينما قدّم في المائدة الجنات ثم قال: ﴿رضي الله عنهم ورضوا عنه﴾؟","answer":"في التوبة كان المقام مقام الثناء على السابقين واتباعهم، فقدم الرضا المتعلق بأعمالهم ثم ثنى بالجزاء؛ وفي المائدة كان المقام مقام جزاء الصادقين يوم القيامة، فقدم الجنة ثم ختم برضا الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص171، تحت المائدة 119.","url":""}]},{"id":"s9-552","number":552,"surah":9,"verses":[100],"verseLabel":"التوبة: 100","question":"ما سرّ التعبير في قوله تعالى في أكثر آيات الجنة: ﴿تجري من تحتها الأنهار﴾، وحذف ﴿من﴾ في التوبة فقال: ﴿تجري تحتها الأنهار﴾؟","answer":"الإثبات بـ﴿من تحتها﴾ يدل على ابتداء جريان الأنهار من تحت الجنات أو أشجارها، وحذف ﴿من﴾ في التوبة يكتفي بتصوير جريانها تحتها؛ والتنويع اللفظي مع بقاء أصل النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص171–172، تحت المائدة 119.","url":""}]},{"id":"s9-553","number":553,"surah":9,"verses":[101],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وممن حولكم من الأعراب منافقون ومن أهل المدينة﴾؟","answer":"قدم منافقي الأعراب المحيطين بالمدينة ثم عطف منافقي أهلها، فدل على إحاطة الخطر من خارج المدينة وداخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص204–207.","url":""}]},{"id":"s9-554","number":554,"surah":9,"verses":[101],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿مردوا على النفاق﴾؟","answer":"﴿مردوا﴾ أي مرنوا وتمرنوا واستمروا على النفاق حتى صار لهم عادة ومهارة، فهو أبلغ من مجرد وقوعهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص206–210.","url":""}]},{"id":"s9-555","number":555,"surah":9,"verses":[101],"verseLabel":"التوبة: 101","question":"ما وجه قوله تعالى للنبي ﷺ: ﴿لا تعلمهم نحن نعلمهم﴾ مع فراسته ووحيه؟","answer":"المنفي علم أشخاص بأعيانهم ممن أخفى النفاق وأتقنه، لا مطلق فراسة النبي ﷺ أو ما أعلمه الله به؛ فعلم الغيب لله ويطلع رسوله على ما يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص209–213.","url":""}]},{"id":"s9-556","number":556,"surah":9,"verses":[101],"verseLabel":"التوبة: 101","question":"لماذا انتقل من الغيبة إلى ضمير العظمة: ﴿نحن نعلمهم سنعذبهم﴾؟","answer":"ضمير العظمة يبرز اختصاص الله بإحاطة العلم بهم وبالقدرة على عقوبتهم، في مقابلة خفائهم عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص212–216.","url":""}]},{"id":"s9-557","number":557,"surah":9,"verses":[101],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿سنعذبهم مرتين﴾ ولم يحدد العذابين؟","answer":"أبهم العذابان ليشملا ما ذكره المفسرون من فضيحة وبلاء في الدنيا وعذاب القبر أو نحو ذلك، وليكون الإبهام أوقع في التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص215–219.","url":""}]},{"id":"s9-558","number":558,"surah":9,"verses":[101],"verseLabel":"التوبة: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يردون إلى عذاب عظيم﴾ بعد العذاب مرتين؟","answer":"بعد عقوبتين قبل القيامة يردون إلى عذاب الآخرة العظيم؛ و﴿ثم﴾ تدل على تراخي المراحل مع تفاوت عظم العذاب الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص218–232.","url":""}]},{"id":"s9-559","number":559,"surah":9,"verses":[102],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرون اعترفوا بذنوبهم﴾ دون ذكر اعتذارهم؟","answer":"الاعتراف الصادق يغني عن الاعتذار المصنوع؛ فهم أقروا بالذنب ولم يحاولوا تزيينه، فتميزوا من المنافقين المعتذرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص233–237.","url":""}]},{"id":"s9-560","number":560,"surah":9,"verses":[102],"verseLabel":"التوبة: 102","question":"لماذا جمع الذنوب مع أن سبب النزول في تخلف واحد؟","answer":"الجمع قد يراد به تعظيم ذنب التخلف وما قارنه من تقصير، أو تعدد الذنوب التي اعترفوا بها؛ فلا يحصر حالهم في فعل منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص236–240.","url":""}]},{"id":"s9-561","number":561,"surah":9,"verses":[102],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿خلطوا عملًا صالحًا وآخر سيئًا﴾، فجعل العملين كشيئين يختلطان؟","answer":"شبهت الأعمال بأشياء مزج بعضها ببعض؛ إذ لم يخلص حالهم للصلاح ولا للسوء، بل اجتمع صدق الإيمان مع معصية التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص239–243.","url":""}]},{"id":"s9-562","number":562,"surah":9,"verses":[102],"verseLabel":"التوبة: 102","question":"ما سرّ تقديم العمل الصالح على السيئ؟","answer":"قدم الصالح لأنه الأصل الغالب في حالهم، وللتنويه بما سبق لهم من إيمان وطاعة فتح باب الرجاء في توبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص242–246.","url":""}]},{"id":"s9-563","number":563,"surah":9,"verses":[102],"verseLabel":"التوبة: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿عسى الله أن يتوب عليهم﴾ مع اعترافهم وندمهم؟","answer":"﴿عسى﴾ من جهة المخاطبين تربيهم بين الرجاء والخوف ولا تجعل التوبة حقًا واجبًا لهم، ووعد الله بها متحقق لمن صدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص245–249.","url":""}]},{"id":"s9-564","number":564,"surah":9,"verses":[102],"verseLabel":"التوبة: 102","question":"لماذا ختم بـ﴿إن الله غفور رحيم﴾؟","answer":"﴿غفور﴾ يستر ذنوب المعترفين إذا تابوا، و﴿رحيم﴾ يقبلهم ويعيدهم إلى أهل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص248–252.","url":""}]},{"id":"s9-565","number":565,"surah":9,"verses":[103],"verseLabel":"التوبة: 103","question":"لماذا أُمر النبي ﷺ أن يأخذ من أموالهم صدقة بعد اعترافهم؟","answer":"كانت الصدقة علامة صدق التوبة وتكفيرًا عن شح النفس وتخلفها، وبأخذها يعودون عمليًا إلى جماعة المؤمنين والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص253–257.","url":""}]},{"id":"s9-566","number":566,"surah":9,"verses":[103],"verseLabel":"التوبة: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿تطهرهم وتزكيهم بها﴾، وما الفرق بين التطهير والتزكية؟","answer":"التطهير إزالة دنس الذنب والبخل، والتزكية تنمية الخير والبركة ورفع المنزلة؛ فالصدقة تزيل النقص وتنمي الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص256–260.","url":""}]},{"id":"s9-567","number":567,"surah":9,"verses":[103],"verseLabel":"التوبة: 103","question":"لماذا أسند التطهير والتزكية إلى النبي ﷺ أو إلى الصدقة بحسب الإعراب؟","answer":"على جعل الضمير للنبي ﷺ يكون أخذه ودعاؤه سببًا في تطهيرهم وتزكيتهم، وعلى عوده إلى الصدقة تكون هي الوسيلة؛ والفاعلية الحقيقية بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص259–263.","url":""}]},{"id":"s9-568","number":568,"surah":9,"verses":[103],"verseLabel":"التوبة: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿وصل عليهم إن صلاتك سكن لهم﴾؟","answer":"الصلاة عليهم دعاء لهم، و﴿سكن﴾ طمأنينة تستقر بها قلوبهم لقبول توبتهم وبركة دعاء الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص262–266.","url":""}]},{"id":"s9-569","number":569,"surah":9,"verses":[103],"verseLabel":"التوبة: 103","question":"لماذا ختم بـ﴿والله سميع عليم﴾؟","answer":"﴿سميع﴾ لدعاء الرسول واعترافهم، و﴿عليم﴾ بصدق نياتهم وتوبتهم؛ فيجازي كلًا على باطنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص265–268.","url":""}]},{"id":"s9-570","number":570,"surah":9,"verses":[104],"verseLabel":"التوبة: 104","question":"لماذا سأل: ﴿ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقات﴾؟","answer":"الاستفهام للتقرير والحض على التوبة والصدقة؛ فالله وحده يقبل توبة عباده ويقبل صدقاتهم، فلا ييأس المذنب ولا يمن بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص269–273.","url":""}]},{"id":"s9-571","number":571,"surah":9,"verses":[104],"verseLabel":"التوبة: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿يقبل التوبة عن عباده﴾ بـ﴿عن﴾ لا «من»؟","answer":"﴿عن﴾ تشعر بالتجاوز والصفح عن الذنب عند قبول التوبة، أما ﴿من﴾ فمجرد ابتداء الأخذ من التائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص272–276.","url":""}]},{"id":"s9-572","number":572,"surah":9,"verses":[104],"verseLabel":"التوبة: 104","question":"ما سرّ نسبة أخذ الصدقات إلى الله مع أن النبي ﷺ هو الذي يأخذها؟","answer":"نسب الأخذ إلى الله لأنه الآمر بالصدقة والمتقبل لها والمثيب عليها، والنبي ﷺ مباشر لأخذها؛ فنسب الفعل إلى مسبب قبوله وغايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص275–279.","url":""}]},{"id":"s9-573","number":573,"surah":9,"verses":[104],"verseLabel":"التوبة: 104","question":"لماذا جاء ضمير الفصل في ﴿وأن الله هو التواب الرحيم﴾؟","answer":"ضمير الفصل ﴿هو﴾ يقصر كمال قبول التوبة والرحمة على الله، ويؤكد أنه كثير التوبة على عباده لا يرده ذنب مع صدق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص278–289.","url":""}]},{"id":"s9-574","number":574,"surah":9,"verses":[105],"verseLabel":"التوبة: 105","question":"لماذا جاء الأمر المطلق: ﴿وقل اعملوا﴾ بعد الحديث عن التوبة والصدقة؟","answer":"الأمر عام ليستأنف التائبون عملًا يصدق توبتهم، ويعلم الجميع أن الاعتبار بما يعملون بعد الدعوى والاعتراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص290–294.","url":""}]},{"id":"s9-575","number":575,"surah":9,"verses":[105],"verseLabel":"التوبة: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيرى الله عملكم ورسوله والمؤمنون﴾؟","answer":"الفاء تصل العمل بنتيجته القريبة: لا يخفى على الله، ويظهر أثره للرسول والمؤمنين؛ ففيها وعد للمحسن ووعيد للمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص293–298.","url":""}]},{"id":"s9-576","number":576,"surah":9,"verses":[105],"verseLabel":"التوبة: 105","question":"لماذا أعيد ذكر رؤية الله والرسول للعمل بعد الآية 94 وزيد هنا ﴿المؤمنون﴾؟","answer":"آية 94 في المنافقين وضمائرهم الخفية، فاقتصر على الله ورسوله بإطلاع الله؛ وهذه في التائبين المؤمنين وأعمالهم الظاهرة، فزاد ﴿المؤمنون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص297–302.","url":""}]},{"id":"s9-577","number":577,"surah":9,"verses":[105],"verseLabel":"التوبة: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿وستردون إلى عالم الغيب والشهادة﴾ بدل «إلى الله»؟","answer":"الوصف يستحضر إحاطة علمه بكل باطن وظاهر عند الرجوع إليه؛ فلا ينفع ستر النية ولا تجميل العمل أمام الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص301–305.","url":""}]},{"id":"s9-578","number":578,"surah":9,"verses":[105],"verseLabel":"التوبة: 105","question":"لماذا ختم بـ﴿فينبئكم بما كنتم تعملون﴾؟","answer":"الإنباء إظهار حقيقة الأعمال والحكم عليها والجزاء بها؛ فهو ختام يربط الأمر بالعمل بالحساب النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص304–309.","url":""}]},{"id":"s9-579","number":579,"surah":9,"verses":[106],"verseLabel":"التوبة: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرون مرجون لأمر الله﴾ بعد ذكر المعترفين التائبين؟","answer":"بعد من اعترفوا وتابوا ذكر فريقًا أُخر حكمهم مؤخر ينتظر أمر الله؛ فميز بين توبة ظهرت وحال لم يُقض فيها بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص290–293.","url":""}]},{"id":"s9-580","number":580,"surah":9,"verses":[106],"verseLabel":"التوبة: 106","question":"لماذا بُني ﴿مرجون﴾ للمجهول؟","answer":"البناء للمجهول يركز على حالهم: مؤخرون موقوف أمرهم، مع العلم بأن المؤخر هو الله؛ وفيه تصوير القلق والانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص292–295.","url":""}]},{"id":"s9-581","number":581,"surah":9,"verses":[106],"verseLabel":"التوبة: 106","question":"لماذا قابل: ﴿إما يعذبهم وإما يتوب عليهم﴾؟","answer":"﴿إما... وإما﴾ تبقيهم بين احتمال العقوبة واحتمال قبول التوبة بحسب علم الله وحكمته، فلا يقطع لهم قبل صدور الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص294–297.","url":""}]},{"id":"s9-582","number":582,"surah":9,"verses":[106],"verseLabel":"التوبة: 106","question":"ما سرّ تقديم احتمال العذاب على التوبة؟","answer":"قدم العذاب لأن سبب استحقاقه، وهو التخلف بلا عذر، متحقق ظاهرًا، أما التوبة ففضل مرجو متعلق بصدق رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص296–298.","url":""}]},{"id":"s9-583","number":583,"surah":9,"verses":[106],"verseLabel":"التوبة: 106","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بحقيقة قلوبهم وتوبتهم، و﴿حكيم﴾ في اختيار العذاب أو القبول؛ فلا يكون التأخير عن جهل أو تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص298–299.","url":""}]},{"id":"s9-584","number":584,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين اتخذوا مسجدًا ضرارًا﴾، فسمى المكان مسجدًا مع فساد قصده؟","answer":"سماه مسجدًا بحسب الصورة والاسم الذي وضعه أصحابه، ثم كشفت الأغراض المنصوبة فساد حقيقته؛ فالعبرة بالمقصد لا بالاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص300–303.","url":""}]},{"id":"s9-585","number":585,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"لماذا عدّد أغراض مسجد الضرار: ضرارًا وكفرًا وتفريقًا وإرصادًا؟","answer":"عددها لكشف طبقات الجريمة: الإضرار بالمؤمنين، وتقوية الكفر، وتفريق الجماعة، وإعداد المكان لمن حارب الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص302–306.","url":""}]},{"id":"s9-586","number":586,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"ما سرّ تقديم الضرار على الكفر؟","answer":"قُدم الضرار لأنه الغرض المباشر الظاهر في بنائه والمتعلق بالمؤمنين، ثم كشف ما وراءه من كفر وتفريق وإرصاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص305–308.","url":""}]},{"id":"s9-587","number":587,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"ما معنى ﴿إرصادًا لمن حارب الله ورسوله﴾؟","answer":"الإرصاد الإعداد والترقب؛ أي اتخذوه موضعًا مهيأ لمن سبق بمحاربة الله ورسوله ليكون قاعدة له عند قدومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص307–311.","url":""}]},{"id":"s9-588","number":588,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿من قبل﴾ بعد ذكر المحاربة؟","answer":"﴿من قبل﴾ تبين أن المحاربة سابقة على بناء المسجد، وأن الإرصاد امتداد لخطة قديمة لا حادثة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص310–313.","url":""}]},{"id":"s9-589","number":589,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"لماذا أكدوا حلفهم: ﴿وليحلفن إن أردنا إلا الحسنى﴾؟","answer":"اللام ونون التوكيد في الحلف تقابلان شناعة مقاصدهم؛ وحصروا إرادتهم في ﴿الحسنى﴾ زاعمين الإحسان والخير لستر الضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص312–316.","url":""}]},{"id":"s9-590","number":590,"surah":9,"verses":[107],"verseLabel":"التوبة: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يشهد إنهم لكاذبون﴾؟","answer":"قابل حلفهم بشهادة الله المحيطة ببواطنهم، وأكد كذبهم بـ﴿إن﴾ واللام؛ فشهادة الله أصدق من أيمانهم المؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص315–320.","url":""}]},{"id":"s9-591","number":591,"surah":9,"verses":[108],"verseLabel":"التوبة: 108","question":"لماذا جاء النهي: ﴿لا تقم فيه أبدًا﴾، ولم يقل: «لا تصل فيه»؟","answer":"القيام أعم من الصلاة، فيشمل الصلاة والإقامة فيه لأي شأن ديني؛ و﴿أبدًا﴾ يقطع صلته بالمشروعية قطعًا دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص300–304.","url":""}]},{"id":"s9-592","number":592,"surah":9,"verses":[108],"verseLabel":"التوبة: 108","question":"لماذا قابل مسجد الضرار بمسجد ﴿أسس على التقوى من أول يوم﴾؟","answer":"المقابلة تكشف أن قيمة المسجد بأساسه وغايته: ذاك أسس للإضرار والكفر، وهذا أسس منذ البدء على تقوى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص303–307.","url":""}]},{"id":"s9-593","number":593,"surah":9,"verses":[108],"verseLabel":"التوبة: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿من أول يوم﴾؟","answer":"تدل على أن التقوى صاحبت تأسيسه من أول لحظة ولم تطرأ عليه بعد ذلك، فثبت إخلاص الأصل واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص306–310.","url":""}]},{"id":"s9-594","number":594,"surah":9,"verses":[108],"verseLabel":"التوبة: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿أحق أن تقوم فيه﴾ مع أن القيام في مسجد الضرار منهي عنه؟","answer":"﴿أحق﴾ للمفاضلة بالنظر إلى دعواهم أن مسجدهم أعد للخير، أي هذا وحده أجدر بالقيام؛ ومع النهي عن الآخر تصير الأحقية تعيينًا لا مشاركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص309–313.","url":""}]},{"id":"s9-595","number":595,"surah":9,"verses":[108],"verseLabel":"التوبة: 108","question":"لماذا وصف أهله بأنهم ﴿يحبون أن يتطهروا﴾، ولم يقل: «يتطهرون»؟","answer":"ذكر محبتهم للتطهر لأنها الدافع الباطني المستمر إلى استعمال أسبابه، والمدح بمحبة الطهارة أبلغ من فعل قد يقع بلا إخلاص أو مداومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص312–317.","url":""}]},{"id":"s9-596","number":596,"surah":9,"verses":[108],"verseLabel":"التوبة: 108","question":"لماذا ختم بـ﴿والله يحب المطهرين﴾؟","answer":"الخاتمة تعلل مدح أهل المسجد: محبتهم للطهارة عمل يحبه الله، وفيها ترغيب في الجمع بين طهارة الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص316–326.","url":""}]},{"id":"s9-597","number":597,"surah":9,"verses":[109],"verseLabel":"التوبة: 109","question":"لماذا صوّر العمل الصالح بأنه بنيان مؤسس على تقوى ورضوان؟","answer":"شُبهت الأعمال ببنيان لأن العقيدة والقصد أساس يحمل العمل؛ فما قام على التقوى ثبت ونفع صاحبه كما يثبت البناء على أصل محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص327–331.","url":""}]},{"id":"s9-598","number":598,"surah":9,"verses":[109],"verseLabel":"التوبة: 109","question":"لماذا جمع بين ﴿تقوى من الله ورضوان﴾؟","answer":"التقوى اجتناب سخط الله وهي أساس العمل، والرضوان غايته وثمرته؛ فجمع سلامة المبدأ وحسن المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص330–334.","url":""}]},{"id":"s9-599","number":599,"surah":9,"verses":[109],"verseLabel":"التوبة: 109","question":"لماذا شبه عمل المنافق ببنيان على ﴿شفا جرف هار﴾؟","answer":"شفا الجرف طرف وادٍ متآكل مشرف على السقوط، فصور عملهم قائمًا على أساس بالغ الضعف ينهار بصاحبه عند أول امتحان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص333–338.","url":""}]},{"id":"s9-600","number":600,"surah":9,"verses":[109],"verseLabel":"التوبة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فانهار به في نار جهنم﴾، فجعل البنيان يهوي بصاحبه؟","answer":"الفاء تصور سرعة الانهيار، والباء في ﴿به﴾ تجعل الباني مصاحبًا لبنيانه في السقوط؛ ففساد العمل يورد صاحبه النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص337–341.","url":""}]},{"id":"s9-601","number":601,"surah":9,"verses":[109],"verseLabel":"التوبة: 109","question":"لماذا ختم بـ﴿والله لا يهدي القوم الظالمين﴾؟","answer":"الظلم وضع العبادة في غير موضعها واتخاذ المسجد للإضرار؛ ومن أصر عليه لا يوفَّق لطريق التقوى والرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص340–349.","url":""}]},{"id":"s9-602","number":602,"surah":9,"verses":[110],"verseLabel":"التوبة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يزال بنيانهم الذي بنوا ريبة في قلوبهم﴾؟","answer":"ظل البناء سبب شك واضطراب في قلوبهم بما تعلق به من نفاق وحسرة بعد هدمه؛ فالجملة تصور دوام أثر الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص350–354.","url":""}]},{"id":"s9-603","number":603,"surah":9,"verses":[110],"verseLabel":"التوبة: 110","question":"لماذا كرر الجذر: ﴿بنيانهم الذي بنوا﴾؟","answer":"التكرار يواجههم بصنيعهم: هذا البنيان المنسوب إليهم هو الذي تعمدوا بناءه، فلا ينفصل أثره عن كسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص353–357.","url":""}]},{"id":"s9-604","number":604,"surah":9,"verses":[110],"verseLabel":"التوبة: 110","question":"لماذا جعل غاية الريبة: ﴿إلا أن تقطع قلوبهم﴾؟","answer":"المعنى أن الريبة تلازمهم إلى أن تتقطع قلوبهم بالموت أو الندم الشديد؛ فجعل لها غاية تهول استمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص356–361.","url":""}]},{"id":"s9-605","number":605,"surah":9,"verses":[110],"verseLabel":"التوبة: 110","question":"لماذا لم يقل: «حتى يموتوا»؟","answer":"﴿تقطع قلوبهم﴾ يصور الموت أو تمزق القلوب بالحسرة تصويرًا محسوسًا، وهو أبلغ من الخبر المباشر عن انتهاء الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص360–364.","url":""}]},{"id":"s9-606","number":606,"surah":9,"verses":[110],"verseLabel":"التوبة: 110","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بنياتهم الخفية في البناء، و﴿حكيم﴾ في كشفه وهدمه وترتيب الجزاء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص345–349.","url":""}]},{"id":"s9-607","number":607,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"لماذا صوّر علاقة المؤمن بالله بالبيع: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم﴾؟","answer":"البيع تمثيل لعهد المؤمن: يبذل نفسه وماله لله في مقابل الجنة، وفي الصورة توثيق للالتزام وتشريف للعوض والمعوَّض.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص350–354.","url":""}]},{"id":"s9-608","number":608,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"ما سرّ تقديم الأنفس هنا على الأموال، بخلاف مواضع الجهاد السابقة؟","answer":"قدمت الأنفس لأن مقام الشراء يذكر أعظم ما يبذل وأغلاه، أو لأن الجنة عوض الحياة أولًا، بخلاف مواضع إعداد الجهاد حيث يقدم المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص353–357.","url":""}]},{"id":"s9-609","number":609,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"ما وجه تصوير المعاملة بالشراء في قوله تعالى: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم﴾ مع أن الله مالكهم ومالك أموالهم؟","answer":"ملك الله لهم أصلي، لكنه عاملهم تفضلًا معاملة المالك المختار، فسمى بذل ما استخلفهم فيه بيعًا وأعطاهم عليه الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص356–360.","url":""}]},{"id":"s9-610","number":610,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"لماذا جعل الثمن ﴿بأن لهم الجنة﴾؟","answer":"الباء للمقابلة، والجنة ثمن كريم دائم لنفس ومال فانيين؛ وفيه إظهار عظم فضل المشتري وربح المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص359–363.","url":""}]},{"id":"s9-611","number":611,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿فيقتلون ويُقتلون﴾، وقدم الفعل المعلوم على المبني للمجهول؟","answer":"قدم ﴿فيقتلون﴾ لإبراز فعلهم في نصرة الحق، ثم ﴿ويقتلون﴾ لبيان استعدادهم للشهادة؛ وفي القراءتين استواء النصر والشهادة في الوفاء بالعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص362–366.","url":""}]},{"id":"s9-612","number":612,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"لماذا ذكر التوراة والإنجيل والقرآن في توثيق الوعد؟","answer":"ذكر الكتب الثلاثة لبيان قدم الوعد وثباته في الشرائع الكبرى، وأنه عهد إلهي واحد لم ينفرد به القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص365–368.","url":""}]},{"id":"s9-613","number":613,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن أوفى بعهده من الله﴾ بصيغة السؤال؟","answer":"الاستفهام إنكاري تقريري: لا أحد أوفى بعهده من الله، فيورث اليقين بالعوض ويزيل كل تردد في الصفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص367–369.","url":""}]},{"id":"s9-614","number":614,"surah":9,"verses":[111],"verseLabel":"التوبة: 111","question":"لماذا ختم بـ﴿فاستبشروا ببيعكم... وذلك هو الفوز العظيم﴾؟","answer":"الأمر بالاستبشار يعلن تمام الصفقة وربحها، واسم الإشارة مع ﴿هو﴾ يقصر الفوز العظيم على هذا البيع المضمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص369–370.","url":""}]},{"id":"s9-615","number":615,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"لماذا جاءت صفات المؤمنين سلسلة أسماء: ﴿التائبون العابدون الحامدون...﴾؟","answer":"الأسماء تدل على ثبوت الصفات ورسوخها، وتعرض المؤمنين كأن كل خصلة صارت سمة معروفة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص371–375.","url":""}]},{"id":"s9-616","number":616,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"لماذا بدأت الصفات بالتوبة؟","answer":"بدأت بالتوبة لأنها تطهر من الموانع وتفتح طريق العبودية؛ فمن رجع عن الذنب استقام له ما بعدها من الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص374–378.","url":""}]},{"id":"s9-617","number":617,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿السائحون﴾، وما صلتها بالصيام أو طلب العلم والجهاد؟","answer":"السياحة مفارقة المألوف في طاعة الله؛ ففسرت بالصيام لانقطاع الصائم عن الشهوات، وبالسفر في طلب العلم أو الجهاد، ويجمعها التجرد للطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص377–381.","url":""}]},{"id":"s9-618","number":618,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"لماذا أفرد الركوع والسجود كصفتين بعد العبادة؟","answer":"خُصا لأنهما أبرز هيئات الصلاة وأدلها على الخضوع، والسجود غاية التذلل؛ ففصلا بعد عموم العبادة للتنويه بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص380–384.","url":""}]},{"id":"s9-619","number":619,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"لماذا عطف ﴿الآمرون بالمعروف والناهون عن المنكر﴾ بالواو بعد صفات بلا عطف؟","answer":"الصفات الأولى تتعلق غالبًا بإصلاح النفس فتتابعت بلا عطف كأنها وصف واحد، ثم عطف الأمر والنهي لانتقالهما إلى إصلاح الغير، مع استقلال كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص383–387.","url":""}]},{"id":"s9-620","number":620,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"لماذا ختم الصفات بـ﴿والحافظون لحدود الله﴾؟","answer":"حفظ الحدود جامع للقيام بالأوامر واجتناب النواهي، فختم به ليستوعب ما لم تفصله الصفات السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص386–389.","url":""}]},{"id":"s9-621","number":621,"surah":9,"verses":[112],"verseLabel":"التوبة: 112","question":"ما سرّ التعبير في قوله تعالى في النهاية: ﴿وبشر المؤمنين﴾ بدل إعادة الصفات؟","answer":"ردهم إلى الاسم الجامع ﴿المؤمنين﴾ لأن تلك الصفات شواهد الإيمان، ولتعم البشارة كل من تحقق بها دون إعادة طويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص388–389.","url":""}]},{"id":"s9-622","number":622,"surah":9,"verses":[113],"verseLabel":"التوبة: 113","question":"لماذا نُهي النبي والمؤمنون عن الاستغفار للمشركين ولو كانوا أولي قربى؟","answer":"إذا تبين موت المشرك على الشرك انقطع محل المغفرة، وقرابة النسب لا تقدم على حق الله ولا تغير حكم الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص390–394.","url":""}]},{"id":"s9-623","number":623,"surah":9,"verses":[113],"verseLabel":"التوبة: 113","question":"لماذا جاء القيد: ﴿من بعد ما تبين لهم أنهم أصحاب الجحيم﴾؟","answer":"قبل التبين يجوز الدعاء رجاء الهداية أو وفاء بوعد سابق، أما بعد العلم بأنه مات على الشرك وثبت له حكم الجحيم فلا معنى للاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص393–397.","url":""}]},{"id":"s9-624","number":624,"surah":9,"verses":[113],"verseLabel":"التوبة: 113","question":"لماذا وصفوا بـ﴿أصحاب الجحيم﴾؟","answer":"الصحبة تفيد الملازمة؛ أي هم أهل الجحيم الملازمون لها، لا عذابًا عابرًا ينتهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص396–402.","url":""}]},{"id":"s9-625","number":625,"surah":9,"verses":[114],"verseLabel":"التوبة: 114","question":"لماذا استغفر إبراهيم لأبيه مع النهي الوارد في الآية السابقة؟","answer":"كان استغفاره عن موعدة وعدها أباه رجاء إيمانه، فلما تبين إصراره وعداوته لله تبرأ منه؛ فلا يعارض النهي بعد التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص403–406.","url":""}]},{"id":"s9-626","number":626,"surah":9,"verses":[114],"verseLabel":"التوبة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما تبين له أنه عدو لله تبرأ منه﴾؟","answer":"الفاء تفيد أن البراءة أعقبت التبين بلا إبطاء، فقدم حق الله على عاطفة الأبوة حين انكشف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص405–409.","url":""}]},{"id":"s9-627","number":627,"surah":9,"verses":[114],"verseLabel":"التوبة: 114","question":"لماذا ختم بوصف إبراهيم: ﴿لأواه حليم﴾؟","answer":"﴿أواه﴾ كثير التضرع والتأوه رحمة، و﴿حليم﴾ لا يعجل بالعقوبة؛ فالوصفان يفسران رفقه واستغفاره قبل التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص408–413.","url":""}]},{"id":"s9-628","number":628,"surah":9,"verses":[115],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليضل قومًا بعد إذ هداهم حتى يبين لهم ما يتقون﴾؟","answer":"نفت الآية أن يؤاخذ الله المهتدين على أمر لم يبين لهم وجوب اتقائه؛ فالحجة والبيان يسبقان المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص414–417.","url":""}]},{"id":"s9-629","number":629,"surah":9,"verses":[115],"verseLabel":"التوبة: 115","question":"لماذا اختيرت لام الجحود في ﴿ليضل﴾؟","answer":"لام الجحود بعد ﴿ما كان﴾ تشدد نفي الإضلال والمؤاخذة بلا بيان، وتفيد أن ذلك لا يليق بعدل الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص416–419.","url":""}]},{"id":"s9-630","number":630,"surah":9,"verses":[115],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إذ هداهم﴾؟","answer":"تذكرهم بنعمة الهداية السابقة وتطمئنهم أنها لا تسلب لمجرد فعل وقع قبل بيان حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص418–421.","url":""}]},{"id":"s9-631","number":631,"surah":9,"verses":[115],"verseLabel":"التوبة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يبين لهم ما يتقون﴾ لا «ما يفعلون»؟","answer":"﴿ما يتقون﴾ يركز على المحظورات التي يجب اجتنابها حتى يسلموا من العقوبة، وهو أنسب بسياق نفي الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص420–423.","url":""}]},{"id":"s9-632","number":632,"surah":9,"verses":[115],"verseLabel":"التوبة: 115","question":"لماذا ختم بـ﴿إن الله بكل شيء عليم﴾؟","answer":"علمه بكل شيء يقتضي علمه بأحوال العباد وما بلّغوا وما خفي عنهم، فيجري البيان والمؤاخذة على عدل تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص423–426.","url":""}]},{"id":"s9-633","number":633,"surah":9,"verses":[116],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله له ملك السماوات والأرض﴾ بعد الحديث عن الهداية والبيان؟","answer":"الملك المطلق دليل قدرته على الهداية والتشريع والجزاء؛ فمن له السماوات والأرض وحده له الحكم والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص427–430.","url":""}]},{"id":"s9-634","number":634,"surah":9,"verses":[116],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿يحيي ويميت﴾ بالمضارع؟","answer":"المضارعان يدلان على تجدد آثار قدرته واستمرارها في إحياء الخلق وإماتتهم، وأن الأمر كله بيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص429–432.","url":""}]},{"id":"s9-635","number":635,"surah":9,"verses":[116],"verseLabel":"التوبة: 116","question":"لماذا نُفي الولي والنصير معًا؟","answer":"الولي يتولى شؤونهم ويجلب النفع، والنصير يدفع الضر؛ فنفيهما يستوعب وجهي الحماية من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص431–434.","url":""}]},{"id":"s9-636","number":636,"surah":9,"verses":[116],"verseLabel":"التوبة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿من دون الله من ولي ولا نصير﴾ بتكرار ﴿من﴾؟","answer":"تكرار ﴿من﴾ في سياق النفي يؤكد الاستغراق: لا يوجد أي ولي ولا أي نصير كائنًا من كان من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص433–437.","url":""}]},{"id":"s9-637","number":637,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد تاب الله على النبي والمهاجرين والأنصار﴾ مع عصمة النبي ﷺ؟","answer":"توبة الله على النبي ﷺ هنا بمعنى إدامة العناية والرضا أو قبول رجوعه إلى الأرفق في شأن المتخلفين، وليست توبة من ذنب ينافي العصمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص438–441.","url":""}]},{"id":"s9-638","number":638,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"ما سرّ تقديم النبي ثم المهاجرين ثم الأنصار؟","answer":"قُدم النبي ﷺ لشرفه وقيادته، ثم المهاجرون لسبقهم، ثم الأنصار لنصرتهم؛ ترتيبًا للرتب مع شمول الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص440–443.","url":""}]},{"id":"s9-639","number":639,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"لماذا سميت الغزوة ﴿ساعة العسرة﴾ مع امتداد زمنها؟","answer":"الساعة تطلق على قطعة من الزمن؛ وإضافتها إلى العسرة تستحضر شدة المرحلة كلها كأنها لحظة حاسمة اجتمعت فيها أسباب الضيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص442–445.","url":""}]},{"id":"s9-640","number":640,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما كاد يزيغ قلوب فريق منهم﴾؟","answer":"﴿كاد﴾ تصور قرب بعضهم من الميل بسبب شدة العسرة، ثم أدركتهم التوبة والعناية قبل وقوع الزيغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص444–447.","url":""}]},{"id":"s9-641","number":641,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"لماذا جُمع ﴿قلوب﴾ مع إفراد ﴿فريق﴾؟","answer":"الفريق مفرد لفظًا دال على جماعة، ولكل فرد قلب؛ لذلك جمع ﴿قلوب﴾ مراعاة للمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص446–449.","url":""}]},{"id":"s9-642","number":642,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"لماذا كرر: ﴿ثم تاب عليهم﴾ بعد قوله: ﴿لقد تاب الله﴾؟","answer":"الأولى شملت النبي والمهاجرين والأنصار إجمالًا، والثانية خصت الفريق الذي قاربت قلوبه الزيغ بتجديد القبول واللطف بعد الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص448–451.","url":""}]},{"id":"s9-643","number":643,"surah":9,"verses":[117],"verseLabel":"التوبة: 117","question":"لماذا ختم بـ﴿إنه بهم رؤوف رحيم﴾؟","answer":"الرأفة أبلغ الرحمة وألطفها، والرحمة أعم؛ فهما تفسران إنقاذهم من الزيغ وقبولهم بعد العسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص451–453.","url":""}]},{"id":"s9-644","number":644,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"لماذا عطف ﴿وعلى الثلاثة الذين خلفوا﴾ دون ذكر أسمائهم؟","answer":"عطفهم على من تاب الله عليهم لإدخالهم في القبول بعد تأخير الحكم، وأبهمت أسماؤهم لأن العبرة بوصفهم وقصتهم لا بذواتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص454–457.","url":""}]},{"id":"s9-645","number":645,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿خُلّفوا﴾ بالبناء للمجهول، لا «تخلفوا»؟","answer":"﴿خُلّفوا﴾ يدل على أن أمرهم أُخّر عن قبول الآخرين، أو خلّفهم الحكم الإلهي، لا مجرد أنهم اختاروا التخلف عن الغزو.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص456–460.","url":""}]},{"id":"s9-646","number":646,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"ما الصورة في قوله: ﴿ضاقت عليهم الأرض بما رحبت﴾؟","answer":"تمثيل لشدة الكرب والوحشة: مع سعة الأرض لم يجدوا مكانًا يطمئنون إليه، فكأنها ضاقت حقيقة حولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص459–462.","url":""}]},{"id":"s9-647","number":647,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"لماذا انتقل من ضيق الأرض إلى ﴿وضاقت عليهم أنفسهم﴾؟","answer":"ضيق الأرض خارجي، ثم بلغ الكرب باطنهم فلم تسعهم نفوسهم؛ فانتقل من إحاطة المكان إلى أشد ضيق نفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص461–464.","url":""}]},{"id":"s9-648","number":648,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أن لا ملجأ من الله إلا إليه﴾؟","answer":"علموا أنه لا مهرب من عقاب الله إلا بالرجوع إليه؛ فجمع التركيب الخوف منه واللجوء إليه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص463–467.","url":""}]},{"id":"s9-649","number":649,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم تاب عليهم ليتوبوا﴾، وما وجه تقدم توبة الله عليهم على توبتهم؟","answer":"توبة الله الأولى توفيقهم للرجوع وفتح بابه لهم، ثم كانت توبتهم، ثم قبلها الله؛ فالتوفيق الإلهي سابق لتوبة العبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص466–470.","url":""}]},{"id":"s9-650","number":650,"surah":9,"verses":[118],"verseLabel":"التوبة: 118","question":"لماذا ختم بـ﴿إن الله هو التواب الرحيم﴾ بضمير الفصل؟","answer":"ضمير الفصل يقصر كمال قبول التوبة والرحمة على الله، ويؤكد أنه كثير القبول لمن صدق مهما اشتد كربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص469–473.","url":""}]},{"id":"s9-651","number":651,"surah":9,"verses":[119],"verseLabel":"التوبة: 119","question":"لماذا جاء بعد قصة الثلاثة الأمر: ﴿اتقوا الله وكونوا مع الصادقين﴾؟","answer":"قصة الثلاثة برهان على نجاة الصدق وهلاك الكذب؛ فجاء الأمر بالتقوى وملازمة الصادقين تعميمًا لعبرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص474–477.","url":""}]},{"id":"s9-652","number":652,"surah":9,"verses":[119],"verseLabel":"التوبة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿مع الصادقين﴾ لا «من الصادقين»؟","answer":"﴿مع﴾ تأمر بملازمة جماعتهم ونصرتهم والسير في طريقهم، وفي ذلك معنى الصحبة العملية المستمرة، لا مجرد الانتساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص477–480.","url":""}]},{"id":"s9-653","number":653,"surah":9,"verses":[120],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله﴾؟","answer":"﴿ما كان﴾ تنفي استحقاق التخلف وتقرر أنه لا يليق بأهل المدينة ومن حولها مع قربهم وقدرة الرسول ﷺ بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص481–484.","url":""}]},{"id":"s9-654","number":654,"surah":9,"verses":[120],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يرغبوا بأنفسهم عن نفسه﴾؟","answer":"لا ينبغي أن يطلبوا لأنفسهم الراحة معرضين عن نفس الرسول ﷺ؛ فحياته ونفسه أولى بالحفظ والبذل من أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص483–487.","url":""}]},{"id":"s9-655","number":655,"surah":9,"verses":[120],"verseLabel":"التوبة: 120","question":"لماذا عدد الظمأ والنصب والمخمصة والموطئ والنيل من العدو؟","answer":"استوعب مشاق الطريق البدنية من عطش وتعب وجوع، وآثار الحركة في أرض العدو، وما يحققونه من إصابة؛ فكل مرحلة مكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص486–491.","url":""}]},{"id":"s9-656","number":656,"surah":9,"verses":[120],"verseLabel":"التوبة: 120","question":"لماذا تكرر ﴿ولا﴾ في تعداد المشاق؟","answer":"التكرار يجعل كل مشقة وعمل مستقلًا في إثبات الأجر، فلا يضيع واحد منها تابعًا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص489–493.","url":""}]},{"id":"s9-657","number":657,"surah":9,"verses":[120],"verseLabel":"التوبة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا كتب لهم به عمل صالح﴾، فجعل المشقة نفسها عملًا؟","answer":"تفضل الله فأجرى ما ليس فعلًا اختياريًا كالظمأ والتعب مجرى العمل الصالح، لأنه نشأ عن مسيرهم في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص492–496.","url":""}]},{"id":"s9-658","number":658,"surah":9,"verses":[120],"verseLabel":"التوبة: 120","question":"لماذا ختم بـ﴿إن الله لا يضيع أجر المحسنين﴾؟","answer":"الخاتمة تضمن حفظ كل مشقة وعمل، وتسميهم محسنين لأنهم بذلوا طاقتهم في نصرة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص496–501.","url":""}]},{"id":"s9-659","number":659,"surah":9,"verses":[121],"verseLabel":"التوبة: 120؛ التوبة: 121","question":"ما سرّ التعبير في قوله تعالى في الآية 120: ﴿إلا كتب لهم به عمل صالح﴾، ثم قال في الآية 121: ﴿إلا كتب لهم﴾ وحذف ﴿به عمل صالح﴾؟","answer":"الآية 120 جمعت مشاقًا ليست أفعالًا لهم مع أعمالهم، فأجراها الله مجرى العمل فقال ﴿به عمل صالح﴾؛ أما 121 فذكرت الإنفاق وقطع الوادي وهما من فعلهم، فاكتفى بـ﴿كتب لهم﴾ أي كتب نفس العمل وثوابه.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص138، https://islamweb.net/ar/library/content/224/10/تفسير-سورة-التوبة.","url":""}]},{"id":"s9-660","number":660,"surah":9,"verses":[121],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينفقون نفقة صغيرة ولا كبيرة﴾؟","answer":"قوبلت الصغيرة بالكبيرة لاستغراق كل نفقة مهما قل قدرها أو كثر، فلا يضيع منها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص502–505.","url":""}]},{"id":"s9-661","number":661,"surah":9,"verses":[121],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يقطعون واديًا إلا كتب لهم﴾؟","answer":"قطع الوادي كناية عن اجتياز المسافات ومشقة السير، وكل واد يجاوزونه يثبت لهم به الأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص504–507.","url":""}]},{"id":"s9-662","number":662,"surah":9,"verses":[121],"verseLabel":"التوبة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿ليجزيهم الله أحسن ما كانوا يعملون﴾، لا «بما كانوا يعملون»؟","answer":"يجزيهم على أعمالهم بأحسن الجزاء، أو يجزي جميع أعمالهم باعتبار أحسنها فضلًا؛ فليس الجزاء مجرد المماثلة بل الإحسان والزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص507–511.","url":""}]},{"id":"s9-663","number":663,"surah":9,"verses":[122],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان المؤمنون لينفروا كافة﴾ بعد الأمر السابق بالنفير؟","answer":"النفير العام لا يجب في كل حال؛ بل تتوزع وظائف الأمة بين الجهاد والتفقه، فلا يخلو الثغر ولا يخلو الناس من العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص512–515.","url":""}]},{"id":"s9-664","number":664,"surah":9,"verses":[122],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿فلولا نفر من كل فرقة منهم طائفة﴾؟","answer":"﴿لولا﴾ للتحضيض، و﴿من كل فرقة طائفة﴾ تحقق الكفاية والتمثيل: يخرج من كل جماعة عدد يحمل العلم أو يبقى للتعلم ثم ينذر قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص514–517.","url":""}]},{"id":"s9-665","number":665,"surah":9,"verses":[122],"verseLabel":"التوبة: 122","question":"لماذا استعمل ﴿نفر﴾ لطالب العلم كما استعمله للجهاد؟","answer":"النفر يدل على الخروج بجد ونشاط لمهمة عظيمة؛ فطلب العلم جهاد يحتاج حركة وبذلًا كما يحتاجه القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص516–518.","url":""}]},{"id":"s9-666","number":666,"surah":9,"verses":[122],"verseLabel":"التوبة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿ليتفقهوا في الدين﴾ لا «ليتعلموا»؟","answer":"التفقه فهم عميق لأحكام الدين ومقاصده يجاوز جمع المعلومات، وهو الذي يؤهل صاحبه للإنذار والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص517–519.","url":""}]},{"id":"s9-667","number":667,"surah":9,"verses":[122],"verseLabel":"التوبة: 122","question":"ما سرّ تقديم التفقه على إنذار القوم؟","answer":"لا يصح الإنذار إلا بعد علم راسخ؛ فقدم إعداد المبلّغ بالتفقه على أثره في قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص519–520.","url":""}]},{"id":"s9-668","number":668,"surah":9,"verses":[122],"verseLabel":"التوبة: 122","question":"لماذا ختم بـ﴿لعلهم يحذرون﴾ لا «يعلمون»؟","answer":"غاية العلم أن يثمر حذرًا وامتثالًا، لا أن يبقى معرفة ذهنية؛ لذلك ختم بالأثر العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص520–521.","url":""}]},{"id":"s9-669","number":669,"surah":9,"verses":[123],"verseLabel":"التوبة: 123","question":"لماذا أمر بقتال ﴿الذين يلونكم من الكفار﴾؟","answer":"البدء بالأقرب تنظيم للقتال ودفع للخطر المباشر، ثم ينتقل إلى من وراءه، وفيه حماية للحدود واستكمال للقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص522–526.","url":""}]},{"id":"s9-670","number":670,"surah":9,"verses":[123],"verseLabel":"التوبة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وليجدوا فيكم غلظة﴾، فجعل الغلظة شيئًا يوجد؟","answer":"جعل الغلظة شيئًا يلقونه في المؤمنين لتظهر في الموقف والثبات بحيث يحسها العدو أثرًا واقعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص525–529.","url":""}]},{"id":"s9-671","number":671,"surah":9,"verses":[123],"verseLabel":"التوبة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿غلظة﴾ لا «قسوة»؟","answer":"الغلظة شدة وحزم في موضع القتال مع بقاء العدل، أما القسوة فغلظ القلب المذموم؛ فاختير اللفظ المنضبط بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص528–532.","url":""}]},{"id":"s9-672","number":672,"surah":9,"verses":[123],"verseLabel":"التوبة: 123","question":"لماذا ختم بـ﴿واعلموا أن الله مع المتقين﴾؟","answer":"المعية وعد بالنصر والتأييد لمن اتقى في قتاله فلم يظلم أو يتجاوز؛ فتجمع الشجاعة والانضباط.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص532–541.","url":""}]},{"id":"s9-673","number":673,"surah":9,"verses":[124],"verseLabel":"التوبة: 124","question":"ما دلالة قول المنافق: ون عند نزول السورة: ﴿أيكم زادته هذه إيمانًا﴾؟","answer":"قالوها استهزاءً وتشكيكًا في أثر الوحي، يسأل بعضهم بعضًا سؤال إنكار لا طلب هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص542–545.","url":""}]},{"id":"s9-674","number":674,"surah":9,"verses":[124],"verseLabel":"التوبة: 124","question":"لماذا نُسبت زيادة الإيمان إلى السورة؟","answer":"نسبت الزيادة إليها لأنها سببها بما تحمل من آيات وبراهين وأحكام، أما خالق الهداية والزيادة فهو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص544–548.","url":""}]},{"id":"s9-675","number":675,"surah":9,"verses":[124],"verseLabel":"التوبة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿فأما الذين آمنوا فزادتهم إيمانًا وهم يستبشرون﴾؟","answer":"الفاء تبين سرعة أثر الوحي في القلوب المؤمنة: يزداد تصديقها وعملها، ويصاحب ذلك استبشار متجدد بنزول الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص547–551.","url":""}]},{"id":"s9-676","number":676,"surah":9,"verses":[125],"verseLabel":"التوبة: 125","question":"ما وجه اختلاف أثر السورة؛ فتزيد المؤمن إيمانًا وتزيد مريض القلب رجسًا؟","answer":"السورة سبب واحد، لكن المحل مختلف: المؤمن يقبلها فتزيد يقينه، والمريض يردها فتضيف كفرًا ونفاقًا إلى ما فيه؛ فالاختلاف في القلوب لا في الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص551–555.","url":""}]},{"id":"s9-677","number":677,"surah":9,"verses":[125],"verseLabel":"التوبة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿فزادتهم رجسًا إلى رجسهم﴾؟","answer":"﴿إلى﴾ تصور انضمام رجس جديد إلى رجس سابق وتراكمه، فكل رد لآية يزيد مرض القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص554–557.","url":""}]},{"id":"s9-678","number":678,"surah":9,"verses":[125],"verseLabel":"التوبة: 125","question":"لماذا ختم بـ﴿وماتوا وهم كافرون﴾؟","answer":"الخاتمة تبين نهاية التراكم: استمر رجسهم حتى خرجوا من الدنيا على الكفر من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص557–562.","url":""}]},{"id":"s9-679","number":679,"surah":9,"verses":[126],"verseLabel":"التوبة: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿أولا يرون أنهم يفتنون في كل عام مرة أو مرتين﴾؟","answer":"الاستفهام للتوبيخ على ترك الاعتبار بالابتلاء المتكرر، و﴿مرة أو مرتين﴾ يدل على أن الفرص تتجدد كل عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص563–566.","url":""}]},{"id":"s9-680","number":680,"surah":9,"verses":[126],"verseLabel":"التوبة: 126","question":"لماذا لم يحدد نوع الفتنة؟","answer":"أبهمت لتشمل أنواع الاختبار من مرض وهزيمة وفضيحة وجهاد وغير ذلك، فالعبرة بتكرر التنبيه لا بنوع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص565–568.","url":""}]},{"id":"s9-681","number":681,"surah":9,"verses":[126],"verseLabel":"التوبة: 126","question":"لماذا جمع بين ﴿لا يتوبون﴾ و﴿لا هم يذكرون﴾؟","answer":"نفت التوبة التي تصلح العمل، ونفت التذكر الذي يوقظ القلب ويفضي إليها؛ فجمع غياب الثمرة وسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص568–572.","url":""}]},{"id":"s9-682","number":682,"surah":9,"verses":[127],"verseLabel":"التوبة: 127","question":"لماذا نظر المنافقون بعضهم إلى بعض عند نزول السورة؟","answer":"تبادلوا النظر خفية يستأذنون بعضهم بعضًا في الانصراف ويتفقدون هل يراهم أحد، فكشفت النظرات تواطؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص573–576.","url":""}]},{"id":"s9-683","number":683,"surah":9,"verses":[127],"verseLabel":"التوبة: 127","question":"ما دلالة قولهم: بنظراتهم: ﴿هل يراكم من أحد﴾؟","answer":"استفهموا بالإشارة خوف افتضاح خروجهم؛ أي هل يراقبنا أحد من المؤمنين قبل أن ننصرف؟","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص575–578.","url":""}]},{"id":"s9-684","number":684,"surah":9,"verses":[127],"verseLabel":"التوبة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم انصرفوا صرف الله قلوبهم﴾؟","answer":"انصرفوا بأبدانهم عن مجلس الوحي، فجازاهم الله بصرف قلوبهم عن الهدى؛ جزاء من جنس فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص578–582.","url":""}]},{"id":"s9-685","number":685,"surah":9,"verses":[127],"verseLabel":"التوبة: 127","question":"لماذا علل صرف القلوب بأنهم ﴿قوم لا يفقهون﴾؟","answer":"عدم الفقه هو سبب انصرافهم ونتيجته: لم يفهموا قيمة الوحي، وبالإعراض ازداد انغلاق قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص582–586.","url":""}]},{"id":"s9-686","number":686,"surah":9,"verses":[128],"verseLabel":"التوبة: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد جاءكم رسول من أنفسكم﴾؟","answer":"اللام و﴿قد﴾ تؤكدان عظم المنة ووقوعها: جاءهم رسول قريب منهم، يعرفون نسبه وصدقه ولسانه وأحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص587–590.","url":""}]},{"id":"s9-687","number":687,"surah":9,"verses":[128],"verseLabel":"التوبة: 128","question":"لماذا اختير ﴿من أنفسكم﴾ لا «منكم» فقط؟","answer":"﴿من أنفسكم﴾ أبلغ في شدة الاتصال، أي من جنسكم وخالص جماعتكم، فكأنه من نفسكم لا غريبًا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص589–592.","url":""}]},{"id":"s9-688","number":688,"surah":9,"verses":[128],"verseLabel":"التوبة: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿عزيز عليه ما عنتم﴾؟","answer":"﴿عزيز عليه﴾ أي شديد شاق عليه عنتكم ومشقتكم؛ فقدم تألمه لما يصيبهم دلالة على غاية الشفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص591–594.","url":""}]},{"id":"s9-689","number":689,"surah":9,"verses":[128],"verseLabel":"التوبة: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿حريص عليكم﴾ وحذف متعلق الحرص؟","answer":"حذف المتعلق ليعم حرصه كل خير لهم: على إيمانهم وهدايتهم ونجاتهم ومصالحهم، لا أمرًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص593–596.","url":""}]},{"id":"s9-690","number":690,"surah":9,"verses":[128],"verseLabel":"التوبة: 128","question":"لماذا خص المؤمنين بقوله: ﴿بالمؤمنين رؤوف رحيم﴾ بعد عموم حرصه على الناس؟","answer":"حرصه عام في دعوة الناس، أما الرأفة والرحمة الخاصة النافعة فبالمؤمنين الذين قبلوا هديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص595–599.","url":""}]},{"id":"s9-691","number":691,"surah":9,"verses":[128],"verseLabel":"التوبة: 128","question":"ما سرّ تقديم ﴿رؤوف﴾ على ﴿رحيم﴾؟","answer":"الرأفة رحمة شديدة تدفع المكروه والضر، فناسب تقديمها بعد ذكر العنت، ثم الرحمة الأعم في جلب الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص598–599.","url":""}]},{"id":"s9-692","number":692,"surah":9,"verses":[129],"verseLabel":"التوبة: 129","question":"لماذا انتقل من وصف رحمة الرسول إلى قوله: ﴿فإن تولوا فقل حسبي الله﴾؟","answer":"بعد بيان بلوغ شفقته أقصى مدى، سلاه إن أعرضوا بأن الله كافيه؛ فعليه البلاغ لا حملهم على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص600–603.","url":""}]},{"id":"s9-693","number":693,"surah":9,"verses":[129],"verseLabel":"التوبة: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿حسبي الله﴾ بالمفرد مع أن المؤمنين مأمورون بالتوكل؟","answer":"الأمر موجه للنبي ﷺ في مقام تسليته وتثبيته، فناسب المفرد ﴿حسبي﴾؛ وكل مؤمن له أن يقولها متوكلًا على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص602–605.","url":""}]},{"id":"s9-694","number":694,"surah":9,"verses":[129],"verseLabel":"التوبة: 129","question":"ما مناسبة إتباع الكفاية بالتوحيد في قوله تعالى: ﴿لا إله إلا هو﴾؟","answer":"الجملة استئناف يقرر وحدانية الله ويعلل كفايته: فهو يكفي رسوله ﷺ لأنه لا معبود بحق ولا مدبر للأمر سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص604–606.","url":""}]},{"id":"s9-695","number":695,"surah":9,"verses":[129],"verseLabel":"التوبة: 129","question":"ما سرّ تقديم الجار والمجرور في قوله تعالى: ﴿عليه توكلت﴾؟","answer":"تقديم ﴿عليه﴾ للاختصاص؛ أي لا أفوض أمري ولا أعتمد إلا على الله، فالتوكل عبادة لا تصرف لسواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص605–607.","url":""}]},{"id":"s9-696","number":696,"surah":9,"verses":[129],"verseLabel":"التوبة: 129","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿وهو رب العرش العظيم﴾؟","answer":"الخاتمة ثناء على عظيم قدرة الله وتعليل للكفاية والتوكل؛ فمن كان رب العرش، أعظم المخلوقات، فهو قادر على نصرة رسوله ﷺ وكفايته ممن تولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص607–609.","url":""}]},{"id":"s10-1","number":1,"surah":10,"verses":[15],"verseLabel":"يونس: 15","question":"لماذا طلبوا: ﴿ائت بقرآن غير هذا أو بدله﴾؟","answer":"طلبوا قرآنًا يقر أصنامهم ولا يذم أهواءهم؛ فهم لم يعترضوا على فصاحته، بل أرادوا تبديل ما جاء به من توحيد وبعث وتشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص10–18، يونس: 15.","url":""}]},{"id":"s10-2","number":2,"surah":10,"verses":[15],"verseLabel":"يونس: 15","question":"ما دلالة قول النبي: ﴿ما يكون لي أن أبدله من تلقاء نفسي﴾؟","answer":"نفى أن يملك تبديله من عند نفسه لأن القرآن وحي يتبع فيه ما يوحى إليه؛ فليس الرسول ﷺ منشئًا للنص حتى يغيره استجابة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص18–28، يونس: 15.","url":""}]},{"id":"s10-3","number":3,"surah":10,"verses":[15],"verseLabel":"يونس: 15","question":"لماذا ختم بقوله: ﴿إني أخاف إن عصيت ربي عذاب يوم عظيم﴾؟","answer":"ختم بالخوف من العذاب لبيان أن تبديل الوحي معصية عظيمة لا يقدم عليها الرسول ﷺ، وفيه رد عملي على طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص28–37، يونس: 15.","url":""}]},{"id":"s10-4","number":4,"surah":10,"verses":[16],"verseLabel":"يونس: 16","question":"لماذا احتج عليهم بقوله: ﴿فقد لبثت فيكم عمرًا من قبله﴾؟","answer":"عاش بينهم زمنًا طويلًا قبل الوحي يعرفون صدقه وأمانته ولم يقل شعرًا أو يتعاط تأليفًا؛ فكيف ينسبون إليه فجأة اختلاق القرآن؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص38–46، يونس: 16.","url":""}]},{"id":"s10-5","number":5,"surah":10,"verses":[16],"verseLabel":"يونس: 16","question":"لماذا ختم الحجة بقوله: ﴿أفلا تعقلون﴾؟","answer":"العقل كاف في وصل مقدمات الحجة بنتيجتها: من عرفوا سيرته وأميته وطول مكثه بينهم ينبغي أن يدركوا أن القرآن ليس من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص46–55، يونس: 16.","url":""}]},{"id":"s10-6","number":6,"surah":10,"verses":[17],"verseLabel":"يونس: 17","question":"لماذا جمع بين ﴿افترى على الله كذبًا﴾ و﴿كذب بآياته﴾؟","answer":"الأول إنشاء للكذب ونسبته إلى الله، والثاني رد للآيات الصادقة بعد مجيئها؛ فجمع طرفي الجريمة: اختلاق الباطل وإنكار الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص56–64، يونس: 17.","url":""}]},{"id":"s10-7","number":7,"surah":10,"verses":[17],"verseLabel":"يونس: 17","question":"لماذا ختم بـ﴿إنه لا يفلح المجرمون﴾؟","answer":"المجرم لا يبلغ مطلوبه ولا ينجو من عاقبته؛ والخاتمة قاعدة تشمل المفترين والمكذبين وتقطع دعوى فلاحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص64–70، يونس: 17.","url":""}]},{"id":"s10-8","number":8,"surah":10,"verses":[18],"verseLabel":"يونس: 18","question":"ما دلالة قولهم: عن الأصنام: ﴿هؤلاء شفعاؤنا عند الله﴾ بدل أن يزعموا أنها تخلق؟","answer":"كانوا يقرون بأن الله الخالق، فلم يقدروا على نسبة الخلق للأصنام، فاختلقوا لها منزلة الشفاعة لتسويغ عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص71–80، يونس: 18.","url":""}]},{"id":"s10-9","number":9,"surah":10,"verses":[18],"verseLabel":"يونس: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿أتنبئون الله بما لا يعلم﴾؟","answer":"الاستفهام تهكم وإنكار: أيخبرون الله بشفعاء لا وجود لهم في ملكه حتى لم يتعلق بهم علمه؟ وما لا يعلمه الله مستحيل الوجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص80–89، يونس: 18.","url":""}]},{"id":"s10-10","number":10,"surah":10,"verses":[19],"verseLabel":"يونس: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿كان الناس أمة واحدة فاختلفوا﴾؟","answer":"كان الناس على أصل التوحيد أو جماعة واحدة ثم طرأ الاختلاف؛ فالنظم يقرر أن التفرق في الدين عارض لا أصل في الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص90–97، يونس: 19.","url":""}]},{"id":"s10-11","number":11,"surah":10,"verses":[19],"verseLabel":"يونس: 19","question":"لماذا أُخّر الفصل بينهم بسبب ﴿كلمة سبقت من ربك﴾؟","answer":"الكلمة السابقة هي تأخير الفصل التام إلى أجل القيامة؛ ولولا هذا القضاء لعوجلوا بالحكم والعقوبة عند اختلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص97–104، يونس: 19.","url":""}]},{"id":"s10-12","number":12,"surah":10,"verses":[20],"verseLabel":"يونس: 20","question":"ما دلالة قولهم: ﴿لولا أنزل عليه آية من ربه﴾ مع كثرة الآيات؟","answer":"أرادوا آية حسية مقترحة توافق تعنتهم، مع أن القرآن والآيات القائمة كافية؛ فليس طلبهم بحثًا عن دليل بل مراوغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص105–112، يونس: 20.","url":""}]},{"id":"s10-13","number":13,"surah":10,"verses":[20],"verseLabel":"يونس: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿فانتظروا إني معكم من المنتظرين﴾؟","answer":"الأمر بالانتظار تهديد: انتظروا الآية أو الحكم، وأنا معكم منتظر ما يقضي الله؛ وستظهر عاقبة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص112–118، يونس: 20.","url":""}]},{"id":"s10-14","number":14,"surah":10,"verses":[21],"verseLabel":"يونس: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿أذقنا الناس رحمة من بعد ضراء مستهم﴾؟","answer":"الإذاقة تجعل الرحمة محسوسة الأثر، و﴿من بعد ضراء مستهم﴾ تبرز سرعة انقلابهم إلى المكر بعد أن باشرهم الضر ثم كشف.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص119–128، يونس: 21.","url":""}]},{"id":"s10-15","number":15,"surah":10,"verses":[21],"verseLabel":"يونس: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا لهم مكر في آياتنا﴾؟","answer":"﴿إذا﴾ الفجائية تصور مبادرتهم إلى الطعن والتكذيب فور الرحمة، بدل الشكر الذي يقتضيه المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص128–137، يونس: 21.","url":""}]},{"id":"s10-16","number":16,"surah":10,"verses":[21],"verseLabel":"يونس: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿الله أسرع مكرًا﴾؟","answer":"المكر الإلهي مجازاتهم وإبطال تدبيرهم من حيث لا يشعرون؛ و﴿أسرع﴾ تبين أن تدبيرهم لا يسبق إحاطة الله وكتابة رسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص129–137، يونس: 21.","url":""}]},{"id":"s10-17","number":17,"surah":10,"verses":[22],"verseLabel":"يونس: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿يسيركم في البر والبحر﴾ ثم انتقل إلى خطابهم: ﴿حتى إذا كنتم في الفلك﴾؟","answer":"بدأ بالغيبة تقريرًا للنعمة على الناس، ثم التفت إلى الخطاب عند دخول الخطر ليضعهم داخل المشهد ويقيم الحجة عليهم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص138–147، يونس: 22.","url":""}]},{"id":"s10-18","number":18,"surah":10,"verses":[22],"verseLabel":"يونس: 22","question":"لماذا جمع بين ﴿ريح طيبة﴾ و﴿جاءتها ريح عاصف﴾؟","answer":"الريح الطيبة توافق فرحهم وأمنهم، ثم الريح العاصف تقلب المشهد إلى خوف؛ فالمقابلة تكشف سرعة تغير الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص147–156، يونس: 22.","url":""}]},{"id":"s10-19","number":19,"surah":10,"verses":[22],"verseLabel":"يونس: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أنهم أحيط بهم﴾؟","answer":"﴿أحيط بهم﴾ تصور الخطر محاصرًا من كل جانب حتى انقطعت أسباب النجاة، فعندها أخلصوا الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص156–164، يونس: 22.","url":""}]},{"id":"s10-20","number":20,"surah":10,"verses":[23],"verseLabel":"يونس: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أنجاهم إذا هم يبغون﴾؟","answer":"الفجاءة في ﴿إذا هم يبغون﴾ تكشف سرعة نقضهم عهد الإخلاص؛ فما إن تحققت النجاة حتى عادوا إلى الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص165–173، يونس: 23.","url":""}]},{"id":"s10-21","number":21,"surah":10,"verses":[23],"verseLabel":"يونس: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما بغيكم على أنفسكم﴾؟","answer":"قصر أثر البغي عليهم؛ فضرره وعقوبته راجعان إلى صاحبه، ولا يضر الله ولا يعجزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص173–184، يونس: 23.","url":""}]},{"id":"s10-22","number":22,"surah":10,"verses":[24],"verseLabel":"يونس: 24","question":"لماذا شبّه الحياة الدنيا بماء أنزله الله من السماء؟","answer":"الماء سبب حياة النبات وسرعة ازدهاره ثم فنائه؛ فبه تجسدت دورة متاع الدنيا من النضارة إلى الزوال المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص185–194، يونس: 24.","url":""}]},{"id":"s10-23","number":23,"surah":10,"verses":[24],"verseLabel":"يونس: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا أخذت الأرض زخرفها وازينت وظن أهلها أنهم قادرون عليها﴾؟","answer":"تراكمت الأفعال حتى بلغ الزخرف غايته واطمأن أهله إلى قدرتهم، فعند تمام الاغترار جاء أمر الله؛ وهذا موضع العبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص194–206، يونس: 24.","url":""}]},{"id":"s10-24","number":24,"surah":10,"verses":[24],"verseLabel":"يونس: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿فجعلناها حصيدًا كأن لم تغن بالأمس﴾؟","answer":"الحصيد نبات مقطوع يابس بعد نضرته، و﴿كأن لم تغن بالأمس﴾ تمحو أثر العمران كأنه لم يقم؛ فصورت سرعة الزوال وكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص198–206، يونس: 24.","url":""}]},{"id":"s10-25","number":25,"surah":10,"verses":[25],"verseLabel":"يونس: 25","question":"لماذا جاءت ﴿والله يدعو إلى دار السلام﴾ بعد مثل الدنيا الزائلة؟","answer":"بعد صورة الدار الزائلة جاء النداء إلى دار السلام الباقية؛ فالمقابلة تنقل القلب من الاغترار بالدنيا إلى اختيار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص207–212، يونس: 25.","url":""}]},{"id":"s10-26","number":26,"surah":10,"verses":[25],"verseLabel":"يونس: 25","question":"لماذا أضاف الجنة إلى ﴿السلام﴾؟","answer":"هي دار السلامة من الموت والحزن والآفات، أو دار الله السلام؛ فالإضافة تجمع الأمان وكرامة القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص212–215، يونس: 25.","url":""}]},{"id":"s10-27","number":27,"surah":10,"verses":[26],"verseLabel":"يونس: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿للذين أحسنوا الحسنى وزيادة﴾؟","answer":"﴿الحسنى﴾ الجنة أو الجزاء الأحسن، و﴿زيادة﴾ فضل فوق الاستحقاق، وأعظمه النظر إلى وجه الله؛ فالثواب إحسان وزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص216–225، يونس: 26.","url":""}]},{"id":"s10-28","number":28,"surah":10,"verses":[26],"verseLabel":"يونس: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يرهق وجوههم قتر ولا ذلة﴾؟","answer":"الرهق غشيان يغطي الوجوه، فنفى عنها سواد الكآبة والذل معًا؛ فظهر الأمن والكرامة على سيمائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص225–233، يونس: 26.","url":""}]},{"id":"s10-29","number":29,"surah":10,"verses":[27],"verseLabel":"يونس: 27","question":"ما سرّ التعبير في قوله تعالى في السيئة: ﴿جزاء سيئة بمثلها﴾، دون أن يقال مثل ما قال في الحسنة: «وزيادة»؟","answer":"العدل يقتضي أن السيئة لا تضاعف بل تجازى بمثلها، أما الحسنة فتزاد فضلًا؛ فافترق مقام العدل عن مقام الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص234–243، يونس: 27.","url":""}]},{"id":"s10-30","number":30,"surah":10,"verses":[27],"verseLabel":"يونس: 27","question":"لماذا شُبهت وجوههم بقطع من الليل مظلمًا؟","answer":"صورت الظلمة تغطي وجوههم قطعًا متراكمة من ليل شديد الإظلام؛ فجمعت السواد والخوف والمهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص243–254، يونس: 27.","url":""}]},{"id":"s10-31","number":31,"surah":10,"verses":[28],"verseLabel":"يونس: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿مكانكم أنتم وشركاؤكم﴾ يوم الحشر؟","answer":"اسم الفعل ﴿مكانكم﴾ يأمرهم بالثبات في موضعهم هم وشركاؤهم للحساب، وفيه زجر يمنع الفرار واختلاط الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص255–263، يونس: 28.","url":""}]},{"id":"s10-32","number":32,"surah":10,"verses":[28],"verseLabel":"يونس: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿فزيلنا بينهم﴾؟","answer":"﴿زيلنا﴾ أي فرقنا وميزنا بينهم بعد اجتماعهم في الدنيا على العبادة؛ فبانت براءة المعبودين وبطلان الصلة المزعومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص263–270، يونس: 28.","url":""}]},{"id":"s10-33","number":33,"surah":10,"verses":[29],"verseLabel":"يونس: 29","question":"ما دلالة قولها: الشركاء: ﴿فكفى بالله شهيدًا بيننا وبينكم﴾؟","answer":"استشهدوا بالله لأنه المحيط بحقيقة الحال، وليكذبوا دعوى العابدين أن عبادتهم كانت بعلمهم ورضاهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص271–277، يونس: 29.","url":""}]},{"id":"s10-34","number":34,"surah":10,"verses":[29],"verseLabel":"يونس: 29","question":"ما دلالة قولهم: ﴿إن كنا عن عبادتكم لغافلين﴾؟","answer":"الغفلة هنا نفي العلم والرضا بعبادتهم؛ فالمعبودون الباطلون لم يشعروا بها أو لم يقروها، فلا تقوم شفاعة مزعومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص277–281، يونس: 29.","url":""}]},{"id":"s10-35","number":35,"surah":10,"verses":[30],"verseLabel":"يونس: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿هنالك تبلو كل نفس ما أسلفت﴾؟","answer":"﴿هنالك﴾ تشير إلى مقام الحساب المهول، و﴿تبلو﴾ أي تختبر أو تتلو وتعاين كل نفس ما قدمت؛ فتنكشف حقيقة العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص282–289، يونس: 30.","url":""}]},{"id":"s10-36","number":36,"surah":10,"verses":[30],"verseLabel":"يونس: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿وردوا إلى الله مولاهم الحق وضل عنهم ما كانوا يفترون﴾؟","answer":"ردوا إلى الله الذي ظهرت ولايته الحقة بعد سقوط الدعاوى، وغاب عنهم ما اختلقوه من آلهة وشفاعة؛ فاجتمع ظهور الحق واضمحلال الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص289–295، يونس: 30.","url":""}]},{"id":"s10-37","number":37,"surah":10,"verses":[31],"verseLabel":"يونس: 31","question":"لماذا تتابعت الأسئلة: من يرزق؟ ومن يملك السمع والأبصار؟ ومن يخرج الحي؟ ومن يدبر الأمر؟","answer":"تدرجت الأسئلة في أصول النعمة والقدرة: الرزق، والحواس، والحياة والموت، وتدبير الكون؛ لتلزمهم بأن المدبر الواحد هو المستحق للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص296–308، يونس: 31.","url":""}]},{"id":"s10-38","number":38,"surah":10,"verses":[31],"verseLabel":"يونس: 31","question":"ما سرّ التعبير بقوله تعالى: بعد اعترافهم: ﴿فقل أفلا تتقون﴾؟","answer":"بعد إقرارهم بربوبيته جاء سؤال التقوى: إذا كان هو الفاعل وحده، أفلا تتقون الشرك وتفردونه بالعبادة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص308–318، يونس: 31.","url":""}]},{"id":"s10-39","number":39,"surah":10,"verses":[32],"verseLabel":"يونس: 32","question":"ما سرّ التعبير في قوله تعالى: ﴿فذلكم الله ربكم الحق فماذا بعد الحق إلا الضلال﴾؟","answer":"اسم الإشارة يعقب اعترافهم ليعين الله الموصوف بتلك الأفعال، ثم تقرر الجملة أن ما جاوز الحق ليس إلا الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص319–327، يونس: 32.","url":""}]},{"id":"s10-40","number":40,"surah":10,"verses":[32],"verseLabel":"يونس: 32","question":"لماذا ختم بقوله: ﴿فأنى تصرفون﴾؟","answer":"الاستفهام للتعجب والتوبيخ: من أي جهة يصرفون عن الحق الواضح بعد أن أقرت به ألسنتهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص327–332، يونس: 32.","url":""}]},{"id":"s10-41","number":41,"surah":10,"verses":[33],"verseLabel":"يونس: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك حقت كلمة ربك على الذين فسقوا أنهم لا يؤمنون﴾؟","answer":"كما ثبت ضلال من عدل عن الحق، ثبت قضاء الله على الخارجين عن طاعته أنهم لا يؤمنون لإصرارهم؛ فالجزاء موافق لفسقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص333–341، يونس: 33.","url":""}]},{"id":"s10-42","number":42,"surah":10,"verses":[34],"verseLabel":"يونس: 34","question":"لماذا أعاد سؤال بدء الخلق وإعادته بعد ذكره في الآية الرابعة؟","answer":"أعيد هنا في سياق محاجة الشركاء ليطالبهم بدليل على قدرتها على البدء والإعادة، بعد تقريره أول السورة أصلًا من أصول العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص342–349، يونس: 34.","url":""}]},{"id":"s10-43","number":43,"surah":10,"verses":[34],"verseLabel":"يونس: 34","question":"لماذا ختم بـ﴿فأنى تؤفكون﴾؟","answer":"﴿تؤفكون﴾ أي تصرفون بالكذب عن الحق؛ والاستفهام يعجب من انقلابهم عن إقرارهم بعجز الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص346–349، يونس: 34.","url":""}]},{"id":"s10-44","number":44,"surah":10,"verses":[35],"verseLabel":"يونس: 35","question":"لماذا سأل: ﴿هل من شركائكم من يهدي إلى الحق﴾ ثم قال: ﴿قل الله يهدي للحق﴾؟","answer":"السؤال يكشف عجز الشركاء حتى عن الهداية، ثم يثبت أن الله وحده يهدي إلى الحق؛ فكيف يعبد العاجز ويترك الهادي؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص350–357، يونس: 35.","url":""}]},{"id":"s10-45","number":45,"surah":10,"verses":[35],"verseLabel":"يونس: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿أفمن يهدي إلى الحق أحق أن يتبع أمن لا يهدي إلا أن يهدى﴾؟","answer":"المقابلة تقيم برهان الأحقية بالاتباع: الله يهدي بذاته، والشريك لا يهتدي فضلًا عن أن يهدي إلا إذا هداه غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص354–359، يونس: 35.","url":""}]},{"id":"s10-46","number":46,"surah":10,"verses":[36],"verseLabel":"يونس: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يتبع أكثرهم إلا ظنًا﴾؟","answer":"القصر يكشف أن مستند أكثرهم ظن وتقليد لا علم؛ و﴿أكثرهم﴾ يحترز ممن قامت له معرفة أو اختلف حاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص360–366، يونس: 36.","url":""}]},{"id":"s10-47","number":47,"surah":10,"verses":[36],"verseLabel":"يونس: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الظن لا يغني من الحق شيئًا﴾؟","answer":"الظن لا يقوم مقام اليقين ولا يدفع شيئًا من الحق الثابت؛ فبطل أن تبنى العقيدة على توهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص363–366، يونس: 36.","url":""}]},{"id":"s10-48","number":48,"surah":10,"verses":[37],"verseLabel":"يونس: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان هذا القرآن أن يفترى من دون الله﴾؟","answer":"﴿ما كان﴾ تنفي إمكان افترائه نفيًا يناسب منزلته ونظمه وموافقته للوحي؛ فلا يليق أن يكون صادرًا من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص367–374، يونس: 37.","url":""}]},{"id":"s10-49","number":49,"surah":10,"verses":[37],"verseLabel":"يونس: 37","question":"لماذا جمع بين ﴿تصديق الذي بين يديه﴾ و﴿تفصيل الكتاب﴾؟","answer":"تصديقه يثبت اتصال الوحي ووحدة أصله، وتفصيله يبين ما يحتاج إليه من العقائد والأحكام؛ فجمع الشهادة لما قبله والبيان لأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص371–378، يونس: 37.","url":""}]},{"id":"s10-50","number":50,"surah":10,"verses":[38],"verseLabel":"يونس: 38","question":"لماذا تحداهم هنا بالإتيان ﴿بسورة مثله﴾؟","answer":"لما زعموا أن محمدًا ﷺ افتراه تحداهم بأقل وحدة مستقلة من جنسه، سورة واحدة، مع دعوة كل من يستطيعون؛ فعجزهم حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص379–386، يونس: 38.","url":""}]},{"id":"s10-51","number":51,"surah":10,"verses":[39],"verseLabel":"يونس: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿بل كذبوا بما لم يحيطوا بعلمه ولما يأتهم تأويله﴾؟","answer":"بادروا بالتكذيب قبل أن يحيطوا بمعانيه وحقائقه وقبل أن تقع أخباره؛ فذمهم على حكم سابق للعلم والتجربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص387–396، يونس: 39.","url":""}]},{"id":"s10-52","number":52,"surah":10,"verses":[40],"verseLabel":"يونس: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من يؤمن به ومنهم من لا يؤمن به﴾؟","answer":"التقسيم يستوعب مآلهم: منهم من سيؤمن أو يصدق باطنًا، ومنهم من يصر؛ والله يعلم حقيقة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص397–402، يونس: 40.","url":""}]},{"id":"s10-53","number":53,"surah":10,"verses":[40],"verseLabel":"يونس: 40","question":"لماذا ختم بـ﴿وربك أعلم بالمفسدين﴾ لا «بالكافرين»؟","answer":"الإفساد يصف أثر كفرهم من صد عن الحق وتكذيب بلا علم، وهو أوسع في بيان الجريمة من مجرد اسم الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص400–402، يونس: 40.","url":""}]},{"id":"s10-54","number":54,"surah":10,"verses":[41],"verseLabel":"يونس: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿لي عملي ولكم عملكم أنتم بريئون مما أعمل وأنا بريء مما تعملون﴾؟","answer":"كررت الضمائر والفواصل لتقرير المفاصلة في المسؤولية: لكل جزاء عمله، ولا يحمل أحد عمل الآخر، مع البراءة المتبادلة من الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص403–408، يونس: 41.","url":""}]},{"id":"s10-55","number":55,"surah":10,"verses":[42],"verseLabel":"يونس: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من يستمعون إليك أفأنت تسمع الصم ولو كانوا لا يعقلون﴾؟","answer":"سماع الصوت بلا عقل للحق بمنزلة الصمم؛ والاستفهام ينفي قدرة الرسول ﷺ على إسماع هداية لمن عطل أدوات الفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص409–414، يونس: 42.","url":""}]},{"id":"s10-56","number":56,"surah":10,"verses":[43],"verseLabel":"يونس: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم من ينظر إليك أفأنت تهدي العمي ولو كانوا لا يبصرون﴾؟","answer":"النظر الظاهر لا ينفع مع عمى البصيرة؛ فلا يملك الرسول ﷺ أن يهدي من اختار ألا يبصر الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص415–425، يونس: 43.","url":""}]},{"id":"s10-57","number":57,"surah":10,"verses":[44],"verseLabel":"يونس: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الله لا يظلم الناس شيئًا ولكن الناس أنفسهم يظلمون﴾؟","answer":"نفى عن الله أدنى ظلم بـ﴿شيئًا﴾، ثم قدم ﴿أنفسهم﴾ ليبين أن ضرر الكفر راجع إليهم وأنهم المتسببون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص426–433، يونس: 44.","url":""}]},{"id":"s10-58","number":58,"surah":10,"verses":[45],"verseLabel":"يونس: 45","question":"لماذا يبدو لهم يوم الحشر أنهم لم يلبثوا إلا ساعة من النهار؟","answer":"لهول الحشر وقصر الدنيا بجانب الآخرة يقدرون مقامهم ساعة، وفي ذلك كشف لغرورهم بما ظنوه طويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص434–447، يونس: 45.","url":""}]},{"id":"s10-59","number":59,"surah":10,"verses":[46],"verseLabel":"يونس: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا مرجعهم﴾؟","answer":"سواء رأى الرسول ﷺ بعض الوعيد في حياته أو توفاه الله قبله، فمرجعهم إليه والحساب واقع؛ فلا يتعلق صدق الوعد بمشاهدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص448–460، يونس: 46.","url":""}]},{"id":"s10-60","number":60,"surah":10,"verses":[47],"verseLabel":"يونس: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل أمة رسول فإذا جاء رسولهم قضي بينهم بالقسط﴾؟","answer":"لكل أمة رسول يقيم الحجة، فإذا جاء يوم الفصل قضى بينهم بالعدل؛ فلا عقوبة بلا رسالة ولا محاباة في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص461–468، يونس: 47.","url":""}]},{"id":"s10-61","number":61,"surah":10,"verses":[48,49],"verseLabel":"يونس: 48–49","question":"لماذا سألوا: ﴿متى هذا الوعد﴾ فأجيبوا بأن الرسول لا يملك لنفسه ضرًا ولا نفعًا؟","answer":"سؤالهم تعجيل استهزاء، فأجيبوا بأن الرسول عبد لا يملك توقيت الضر والنفع حتى لنفسه؛ لكل أمة أجل يقدره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص469–483، يونس: 48–49.","url":""}]},{"id":"s10-62","number":62,"surah":10,"verses":[49],"verseLabel":"يونس: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا جاء أجلهم فلا يستأخرون ساعة ولا يستقدمون﴾؟","answer":"إذا حضر الأجل لا يمكنهم تأخيره ولا تقديمه مقدار ساعة؛ فالتعبير ينفي التصرف في جهتي الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص476–483، يونس: 49.","url":""}]},{"id":"s10-63","number":63,"surah":10,"verses":[50,51],"verseLabel":"يونس: 50–51","question":"ما سرّ التعبير في قوله تعالى: ﴿أثم إذا ما وقع آمنتم به آلآن﴾؟","answer":"﴿أثم﴾ تستنكر تأخير الإيمان إلى وقوع العذاب، و﴿آلآن﴾ توبيخ على طلب القبول بعد زوال زمن الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص484–499، يونس: 50–51.","url":""}]},{"id":"s10-64","number":64,"surah":10,"verses":[52],"verseLabel":"يونس: 52","question":"ما سرّ التعبير بقوله تعالى: ﴿ذوقوا عذاب الخلد﴾؟","answer":"الذوق يجعل العذاب مباشرًا محسوسًا، وإضافته إلى الخلد تبين أنه عذاب دائم لا تجربة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص500–507، يونس: 52.","url":""}]},{"id":"s10-65","number":65,"surah":10,"verses":[53],"verseLabel":"يونس: 53","question":"لماذا أُمر النبي أن يقسم: ﴿إي وربي إنه لحق﴾؟","answer":"أكد الجواب بالقسم ﴿إي وربي﴾ لمواجهة استنبائهم على سبيل الإنكار، وأتبع بأنه حق وأنهم لا يعجزون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص508–516، يونس: 53.","url":""}]},{"id":"s10-66","number":66,"surah":10,"verses":[54],"verseLabel":"يونس: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿لو أن لكل نفس ظلمت ما في الأرض لافتدت به﴾؟","answer":"لو ملكت النفس الظالمة جميع ما في الأرض لبذلته فداءً؛ فالشرط يصور بلوغ الهول حد سقوط قيمة الدنيا كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص517–525، يونس: 54.","url":""}]},{"id":"s10-67","number":67,"surah":10,"verses":[54],"verseLabel":"يونس: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وأسروا الندامة لما رأوا العذاب﴾؟","answer":"أخفوا الندامة أو بدت عليهم بحيث بهتوا فلم يقدروا على إظهارها؛ فجاء الإسرار عند معاينة عذاب لا مهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص525–535، يونس: 54.","url":""}]},{"id":"s10-68","number":68,"surah":10,"verses":[55],"verseLabel":"يونس: 55","question":"لماذا كرر ﴿ألا﴾ في: ﴿ألا إن لله ما في السماوات والأرض ألا إن وعد الله حق﴾؟","answer":"الأولى تنبه إلى ملك الله الذي يضمن القدرة، والثانية إلى صدق وعده؛ فتكرار أداة التنبيه يوقظ لكل حقيقة مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص536–545، يونس: 55.","url":""}]},{"id":"s10-69","number":69,"surah":10,"verses":[56],"verseLabel":"يونس: 56","question":"لماذا جمع في عبارة قصيرة: ﴿هو يحيي ويميت وإليه ترجعون﴾؟","answer":"جمع أصل القدرة والمصير: يحيي ويميت وحده ثم يرجع الجميع إليه، فلا مهرب من بعثه وحسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص546–552، يونس: 56.","url":""}]},{"id":"s10-70","number":70,"surah":10,"verses":[57],"verseLabel":"يونس: 57","question":"لماذا وصف القرآن بأنه ﴿موعظة﴾ و﴿شفاء﴾ و﴿هدى﴾ و﴿رحمة﴾ بهذا الترتيب؟","answer":"الموعظة تزجر عن الشر، والشفاء يزيل أمراض القلب، والهدى يدل على الطريق، والرحمة توصل إلى الخير؛ ترتيب من التنقية إلى التكميل والثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص553–568، يونس: 57.","url":""}]},{"id":"s10-71","number":71,"surah":10,"verses":[57],"verseLabel":"يونس: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿شفاء لما في الصدور﴾؟","answer":"الصدور موطن القلوب وما تخفيه من شك وشرك وحسد؛ فالقرآن يعالج العلل الباطنة لا أعراض الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص558–568، يونس: 57.","url":""}]},{"id":"s10-72","number":72,"surah":10,"verses":[58],"verseLabel":"يونس: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿بفضل الله وبرحمته فبذلك فليفرحوا﴾؟","answer":"تقديم فضل الله ورحمته يحصر سبب الفرح الحق فيهما، و﴿فبذلك﴾ يعيدهما للتعظيم، والأمر يوجه الفرح إلى الوحي والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص569–584، يونس: 58.","url":""}]},{"id":"s10-73","number":73,"surah":10,"verses":[58],"verseLabel":"يونس: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿هو خير مما يجمعون﴾ لا «مما يملكون»؟","answer":"﴿يجمعون﴾ يصور سعيهم المتكرر لتكديس متاع الدنيا، ففضل الله خير من المجموع ومن فعل الجمع نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص577–584، يونس: 58.","url":""}]},{"id":"s10-74","number":74,"surah":10,"verses":[59],"verseLabel":"يونس: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿أرأيتم ما أنزل الله لكم من رزق فجعلتم منه حرامًا وحلالًا﴾؟","answer":"﴿أنزل﴾ يفيد أن الرزق من عطاء الله وتقديره، ثم فضح تصرفهم فيه بالتحليل والتحريم بلا إذن المالك.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص585–594، يونس: 59.","url":""}]},{"id":"s10-75","number":75,"surah":10,"verses":[59],"verseLabel":"يونس: 59","question":"لماذا خُتم السؤال بـ﴿آلله أذن لكم أم على الله تفترون﴾؟","answer":"حصر الاحتمالين: إما إذن من الله بدليل، وإما افتراء عليه؛ ولما لم يوجد الإذن ثبت الافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص594–600، يونس: 59.","url":""}]},{"id":"s10-76","number":76,"surah":10,"verses":[60],"verseLabel":"يونس: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿وما ظن الذين يفترون على الله الكذب يوم القيامة﴾؟","answer":"السؤال يهوّل ما ينتظر المفترين يوم القيامة: أي ظن لهم بربهم وبمصيرهم حين ينكشف كذبهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص601–614، يونس: 60.","url":""}]},{"id":"s10-77","number":77,"surah":10,"verses":[61],"verseLabel":"يونس: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تكون في شأن وما تتلو منه من قرآن ولا تعملون من عمل إلا كنا عليكم شهودًا﴾؟","answer":"استوعبت الجملة أحوال الرسول ﷺ في شأنه وتلاوته، وأعمال الأمة، ثم أثبتت شهود الله حال مباشرتها؛ فلا يغيب فعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص615–628، يونس: 61.","url":""}]},{"id":"s10-78","number":78,"surah":10,"verses":[61],"verseLabel":"يونس: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يعزب عن ربك من مثقال ذرة﴾؟","answer":"العزوب الغياب والبعد، فنفاه عن مثقال ذرة في الأرض أو السماء، ثم عمم الأصغر والأكبر في كتاب مبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص628–643، يونس: 61.","url":""}]},{"id":"s10-79","number":79,"surah":10,"verses":[62,63],"verseLabel":"يونس: 62–63","question":"لماذا عرّف أولياء الله بقوله: ﴿الذين آمنوا وكانوا يتقون﴾؟","answer":"عرّفهم بأصلين جامعين: إيمان صحيح وتقوى مستمرة؛ فالولاية ليست دعوى أو كرامة مجردة بل تصديق وطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص644–652، يونس: 62–63.","url":""}]},{"id":"s10-80","number":80,"surah":10,"verses":[62],"verseLabel":"يونس: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿لا خوف عليهم ولا هم يحزنون﴾؟","answer":"نفي الخوف يتعلق بما يستقبل، ونفي الحزن بما مضى؛ فاستوعب أمنهم الزمني، وأكد الثاني بالضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص644–657، يونس: 62–63.","url":""}]},{"id":"s10-81","number":81,"surah":10,"verses":[64],"verseLabel":"يونس: 64","question":"ما المقصود بالبشرى لهم في الحياة الدنيا وفي الآخرة؟","answer":"في الدنيا ما يثبتهم من الرؤيا الصالحة والبشارة والذكر الحسن، وفي الآخرة بشارة الملائكة والجنة والرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص658–669، يونس: 64.","url":""}]},{"id":"s10-82","number":82,"surah":10,"verses":[65],"verseLabel":"يونس: 65","question":"ما سرّ التعبير بقوله تعالى: للنبي: ﴿ولا يحزنك قولهم إن العزة لله جميعًا﴾؟","answer":"نهاه عن الحزن لأن أقوالهم لا تنقص عزة الحق؛ فالعزة كلها لله، وهو السميع لقولهم العليم بمكرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص670–682، يونس: 65.","url":""}]},{"id":"s10-83","number":83,"surah":10,"verses":[66],"verseLabel":"يونس: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿ألا إن لله من في السماوات ومن في الأرض﴾ بـ﴿من﴾؟","answer":"﴿من﴾ تستعمل للعقلاء، فدل على ملكه كل ذي إرادة في السماوات والأرض، ومن باب أولى ما سواهم؛ فلا يملك الشركاء أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص683–691، يونس: 66.","url":""}]},{"id":"s10-84","number":84,"surah":10,"verses":[66],"verseLabel":"يونس: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿إن يتبعون إلا الظن وإن هم إلا يخرصون﴾؟","answer":"قصر اتباعهم على الظن وقصر قولهم على التخمين والكذب؛ فليس وراء الشرك علم ولا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص691–698، يونس: 66.","url":""}]},{"id":"s10-85","number":85,"surah":10,"verses":[67],"verseLabel":"يونس: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿جعل لكم الليل لتسكنوا فيه والنهار مبصرًا﴾؟","answer":"جعل الليل ظرفًا للسكون، ووصف النهار نفسه بالإبصار لما يظهر فيه من الأشياء؛ فجمع راحة الظلمة ووضوح الضوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص699–710، يونس: 67.","url":""}]},{"id":"s10-86","number":86,"surah":10,"verses":[67],"verseLabel":"يونس: 67","question":"لماذا ختم بـ﴿لقوم يسمعون﴾؟","answer":"الآيات ينتفع بها من يسمع سماع تدبر وقبول؛ فالسمع مدخل الموعظة التي تقود إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص707–710، يونس: 67.","url":""}]},{"id":"s10-87","number":87,"surah":10,"verses":[68],"verseLabel":"يونس: 68","question":"لماذا رد على قولهم: ﴿اتخذ الله ولدًا﴾ بقوله: ﴿سبحانه هو الغني﴾؟","answer":"نزه نفسه ثم أثبت غناه المطلق؛ والغني عن كل شيء لا يحتاج إلى ولد يعينه أو يرثه، وإنما الولد حاجة المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص711–719، يونس: 68.","url":""}]},{"id":"s10-88","number":88,"surah":10,"verses":[68],"verseLabel":"يونس: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿أتقولون على الله ما لا تعلمون﴾؟","answer":"الاستفهام إنكار وتوبيخ على نسبة أعظم الدعوى إلى الله بلا علم ولا سلطان؛ فالقول عليه بغير علم افتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص719–725، يونس: 68.","url":""}]},{"id":"s10-89","number":89,"surah":10,"verses":[69,70],"verseLabel":"يونس: 69–70","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الذين يفترون على الله الكذب لا يفلحون متاع في الدنيا ثم إلينا مرجعهم﴾؟","answer":"نفى عن المفترين الفلاح، ثم بين أن ما لهم متاع قصير في الدنيا يعقبه الرجوع والعذاب؛ فلا يناقض ظاهر النعمة خسرانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص726–738، يونس: 69–70.","url":""}]},{"id":"s10-90","number":90,"surah":10,"verses":[71],"verseLabel":"يونس: 71","question":"ما دلالة قول نوح: ﴿إن كان كبر عليكم مقامي وتذكيري بآيات الله﴾؟","answer":"﴿كبر عليكم﴾ أي شق وثقل مقامي بينهم وتذكيري المتكرر؛ فصرح بسبب عداوتهم ثم أعلن توكله.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص739–750، يونس: 71.","url":""}]},{"id":"s10-91","number":91,"surah":10,"verses":[71],"verseLabel":"يونس: 71","question":"لماذا تحداهم: ﴿فأجمعوا أمركم وشركاءكم ثم لا يكن أمركم عليكم غمة ثم اقضوا إلي ولا تنظرون﴾؟","answer":"الأوامر للتحدي والتعجيز: اجمعوا تدبيركم وشركاءكم واجعلوه واضحًا ثم نفذوا حكمكم فورًا؛ وثقته بالله تكشف عجزهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص750–763، يونس: 71.","url":""}]},{"id":"s10-92","number":92,"surah":10,"verses":[72],"verseLabel":"يونس: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن توليتم فما سألتكم من أجر﴾؟","answer":"إن أعرضوا فلا تهمة له في دعوته؛ لم يطلب مالًا، وأجره على الله، ومهمته الاستسلام لله وتبليغ رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص764–774، يونس: 72.","url":""}]},{"id":"s10-93","number":93,"surah":10,"verses":[73],"verseLabel":"يونس: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فكذبوه فنجيناه ومن معه في الفلك وجعلناهم خلائف﴾؟","answer":"تعاقب الفاءات سرعة الجزاء بعد التكذيب: نجاة نوح ومن معه، واستخلافهم في الأرض، وإغراق المكذبين؛ فظهرت عاقبتا الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص775–783، يونس: 73.","url":""}]},{"id":"s10-94","number":94,"surah":10,"verses":[74],"verseLabel":"يونس: 74","question":"ما سرّ التعبير في قوله تعالى عن الأمم بعد نوح: ﴿فما كانوا ليؤمنوا بما كذبوا به من قبل﴾؟","answer":"أصروا بعد مجيء البينات بسبب تكذيبهم السابق حتى صار مانعًا راسخًا من الإيمان؛ وهكذا يطبع الله على قلوب المعتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص784–793، يونس: 74.","url":""}]},{"id":"s10-95","number":95,"surah":10,"verses":[75],"verseLabel":"يونس: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم بعثنا من بعدهم موسى وهارون إلى فرعون وملئه﴾؟","answer":"﴿ثم﴾ تفيد التراخي بعد الرسل السابقين، وذكر موسى وهارون معًا يبرز اشتراكهما في الرسالة إلى فرعون وملئه، وهم قادة الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج19، ص794–نهاية الجزء، يونس: 75.","url":""}]},{"id":"s11-1","number":1,"surah":11,"verses":[1],"verseLabel":"هود: 1","question":"لماذا وصف الكتاب أولًا بأن آياته ﴿أحكمت﴾ ثم قال: ﴿ثم فصلت﴾؟","answer":"لأن الإحكام يدل على كمال نظمه ومنعه من الخلل، والتفصيل يدل على بيان معانيه وأحكامه وتنوع مقاصده؛ فجمع له كمال البناء وكمال البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص375–384، هود: 1.","url":""}]},{"id":"s11-2","number":2,"surah":11,"verses":[1],"verseLabel":"هود: 1","question":"لماذا ختم الآية بـ﴿من لدن حكيم خبير﴾؟","answer":"لأن إحكام الآيات يناسب اسم ﴿الحكيم﴾، وتفصيلها على وفق مصالح الخلق يناسب ﴿الخبير﴾؛ فالخاتمة دليل على ما سبقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص375–384، هود: 1.","url":""}]},{"id":"s11-3","number":3,"surah":11,"verses":[2],"verseLabel":"هود: 2","question":"لماذا بدأت رسالة السورة بالنهي: ﴿ألا تعبدوا إلا الله﴾ قبل ذكر البشارة؟","answer":"لأن إزالة الشرك أصل يسبق بناء سائر الطاعات، ثم جاء الإنذار والبشارة ليحركا القلب بالخوف والرجاء بعد تصحيح وجهة العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص385–391، هود: 2.","url":""}]}]);
